/**
 * Strip empty-string / empty-array / nullish keys — the exact normalization
 * the form emits via `onValuesChange`. Exported so callers can compute a dirty
 * baseline on the same footing (otherwise an entity with a stored empty field
 * reads as dirty on mount).
 */
export function cleanFormData(
	data: Record<string, unknown>,
): Record<string, unknown> {
	const cleaned: Record<string, unknown> = {};
	for (const [key, value] of Object.entries(data)) {
		if (value === null || value === undefined || value === "") continue;
		if (Array.isArray(value) && value.length === 0) continue;
		cleaned[key] = value;
	}
	return cleaned;
}
