// lobu.config.ts — Prodma ERP proof of concept
//
// The Quote → Invoice slice of a Turkish manufacturing ERP, modelled as Lobu
// entity types. Every rule here is DATA on the type, not code: `x-transitions`
// declares the document lifecycle, `x-link-entity-type` declares the foreign
// keys. Both are read at runtime, so an agent can change them with no deploy.

import {
  defineAgent,
  defineConfig,
  defineEntityType,
  secret,
} from "@lobu/cli/config";

// --- Master data -----------------------------------------------------------

const customer = defineEntityType({
  key: "customer",
  name: "Customer",
  required: ["title"],
  properties: {
    title: { type: "string", "x-table-label": "Unvan", "x-table-column": true },
    tax_office: { type: "string", "x-table-label": "Vergi Dairesi" },
    tax_number: {
      type: "string",
      "x-table-label": "VKN/TCKN",
      "x-table-column": true,
    },
    city: { type: "string", "x-table-label": "Şehir", "x-table-column": true },
    email: { type: "string", format: "email", "x-table-label": "E-posta" },
    phone: { type: "string", "x-table-label": "Telefon" },
    payment_term_days: {
      type: "integer",
      default: 30,
      "x-table-label": "Vade (gün)",
      "x-table-column": true,
    },
    currency: { type: "string", enum: ["TRY", "USD", "EUR"], default: "TRY" },
    is_einvoice_user: {
      type: "boolean",
      default: false,
      "x-table-label": "e-Fatura",
      "x-table-column": true,
    },
  },
});

const product = defineEntityType({
  key: "product",
  name: "Product",
  required: ["title", "unit"],
  properties: {
    title: { type: "string", "x-table-label": "Stok Adı", "x-table-column": true },
    code: { type: "string", "x-table-label": "Stok Kodu", "x-table-column": true },
    unit: {
      type: "string",
      enum: ["ADET", "KG", "MT", "M2", "PAKET"],
      "x-table-label": "Birim",
      "x-table-column": true,
    },
    list_price: {
      type: "number",
      "x-table-label": "Liste Fiyatı",
      "x-table-column": true,
    },
    vat_rate: {
      type: "number",
      enum: [0, 1, 10, 20],
      default: 20,
      "x-table-label": "KDV %",
      "x-table-column": true,
    },
    on_hand: { type: "number", default: 0, "x-table-label": "Stok" },
  },
});

// --- Documents -------------------------------------------------------------

/** One line of a document. Shared shape across quote / invoice. */
const documentLines = {
  type: "array" as const,
  "x-table-label": "Satırlar",
  items: {
    type: "object" as const,
    required: ["product_id", "quantity", "unit_price", "vat_rate"],
    properties: {
      product_id: {
        type: "integer",
        "x-link-entity-type": "product",
        "x-link-lookup-field": "title",
      },
      description: { type: "string" },
      quantity: { type: "number" },
      unit_price: { type: "number" },
      vat_rate: { type: "number", enum: [0, 1, 10, 20] },
      line_total: { type: "number", readOnly: true },
    },
  },
};

const quote = defineEntityType({
  key: "quote",
  name: "Quote",
  required: ["customer_id", "date", "status"],
  properties: {
    // The lifecycle, declared as data. Nothing in the published server reads
    // this yet — that is exactly what the freeze spike is for.
    document_no: { type: "string", "x-table-label": "Teklif No", "x-table-column": true },
    status: {
      type: "string",
      enum: ["draft", "sent", "accepted", "rejected"],
      default: "draft",
      "x-table-label": "Durum",
      "x-table-column": true,
    },
    date: { type: "string", format: "date", "x-table-label": "Tarih", "x-table-column": true },
    valid_until: { type: "string", format: "date", "x-table-label": "Geçerlilik" },
    customer_id: {
      type: "integer",
      "x-link-entity-type": "customer",
      "x-link-lookup-field": "title",
      "x-table-label": "Cari",
      "x-table-column": true,
    },
    currency: { type: "string", enum: ["TRY", "USD", "EUR"], default: "TRY" },
    lines: documentLines,
    subtotal: { type: "number", readOnly: true, "x-table-label": "Ara Toplam" },
    vat_total: { type: "number", readOnly: true, "x-table-label": "KDV" },
    grand_total: {
      type: "number",
      readOnly: true,
      "x-table-label": "Genel Toplam",
      "x-table-column": true,
    },
    notes: { type: "string" },
  },
});

const invoice = defineEntityType({
  key: "invoice",
  name: "Invoice",
  required: ["customer_id", "date", "status"],
  properties: {
    document_no: { type: "string", "x-table-label": "Fatura No", "x-table-column": true },
    status: {
      type: "string",
      enum: ["draft", "issued", "posted", "cancelled"],
      default: "draft",
      "x-table-label": "Durum",
      "x-table-column": true,
    },
    date: { type: "string", format: "date", "x-table-label": "Tarih", "x-table-column": true },
    due_date: { type: "string", format: "date", "x-table-label": "Vade" },
    customer_id: {
      type: "integer",
      "x-link-entity-type": "customer",
      "x-link-lookup-field": "title",
      "x-table-label": "Cari",
      "x-table-column": true,
    },
    quote_id: {
      type: "integer",
      "x-link-entity-type": "quote",
      "x-link-lookup-field": "document_no",
      "x-table-label": "Teklif",
    },
    currency: { type: "string", enum: ["TRY", "USD", "EUR"], default: "TRY" },
    fx_rate: { type: "number", default: 1 },
    lines: documentLines,
    subtotal: { type: "number", readOnly: true, "x-table-label": "Ara Toplam" },
    vat_total: { type: "number", readOnly: true, "x-table-label": "KDV" },
    grand_total: {
      type: "number",
      readOnly: true,
      "x-table-label": "Genel Toplam",
      "x-table-column": true,
    },
    einvoice_uuid: { type: "string", "x-table-label": "e-Fatura UUID" },
  },
});

const payment = defineEntityType({
  key: "payment",
  name: "Payment",
  required: ["customer_id", "date", "amount"],
  properties: {
    date: { type: "string", format: "date", "x-table-label": "Tarih", "x-table-column": true },
    customer_id: {
      type: "integer",
      "x-link-entity-type": "customer",
      "x-link-lookup-field": "title",
      "x-table-label": "Cari",
      "x-table-column": true,
    },
    invoice_id: {
      type: "integer",
      "x-link-entity-type": "invoice",
      "x-link-lookup-field": "document_no",
      "x-table-label": "Fatura",
    },
    amount: { type: "number", "x-table-label": "Tutar", "x-table-column": true },
    currency: { type: "string", enum: ["TRY", "USD", "EUR"], default: "TRY" },
    method: {
      type: "string",
      enum: ["KASA", "BANKA", "CEK", "SENET"],
      "x-table-label": "Tahsilat Tipi",
      "x-table-column": true,
    },
  },
});

const agent = defineAgent({
  id: "prodma-demo",
  name: "Prodma",
  description:
    "ERP assistant for a Turkish manufacturing company — quotes, invoices, customer balances.",
  dir: "./agents/prodma-demo",
  providers: [
    {
      id: "claude",
      key: secret("ANTHROPIC_API_KEY"),
    },
  ],
  network: {
    allowed: [
      "registry.npmjs.org",
      ".npmjs.org",
      "github.com",
      ".github.com",
      ".githubusercontent.com",
      "cdn.jsdelivr.net",
      "unpkg.com",
      "pypi.org",
      "files.pythonhosted.org",
    ],
  },
});

export default defineConfig({
  agents: [agent],
  entities: [customer, product, quote, invoice, payment],
});

