// Realistic Prodma dataset: enough rows that the CRUD pages have to page,
// filters have to matter, and the agent has to actually search rather than
// eyeball a list of three. Deterministic (seeded LCG) so a re-seed reproduces.
export default async (_ctx, client) => {
  let s = 20260814;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const pick = (a) => a[Math.floor(rnd() * a.length)];
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const money = (n) => Math.round(n * 100) / 100;

  const existing = await client.entities.list({ entity_type: "customer", limit: 200 });
  if ((existing.entities ?? []).length > 5) return { skipped: "already seeded", count: existing.entities.length };

  const cities = ["Istanbul", "Izmir", "Bursa", "Ankara", "Konya", "Kocaeli", "Gaziantep", "Denizli", "Kayseri", "Manisa"];
  const offices = ["Kozyatagi", "Bornova", "Nilufer", "Cankaya", "Selcuklu", "Gebze", "Sehitkamil", "Merkez", "Melikgazi", "Sehzadeler"];
  const stems = ["Anadolu Makina Sanayi", "Ege Plastik", "Konya Tarim Makinalari", "Marmara Metal Isleme", "Toros Kimya",
    "Yildiz Kalip", "Akdeniz Dokum", "Trakya Otomotiv Yan Sanayi", "Bosphorus Endustri", "Selcuk Civata",
    "Karadeniz Celik", "Ova Gida Makinalari", "Nova Hidrolik", "Demir Pres", "Atlas Vinc",
    "Guney Kablo", "Cukurova Tarim", "Ilkay Metal", "Pamukkale Tekstil Makina", "Baris Sogutma",
    "Onder Ambalaj", "Kartal Rulman", "Genc Otomasyon", "Sirius Elektrik", "Volkan Isi Sistemleri"];
  const suffixes = ["A.S.", "Ltd. Sti.", "San. ve Tic. A.S.", "San. Tic. Ltd. Sti."];

  const customers = [];
  for (let i = 0; i < stems.length; i++) {
    const md = {
      title: `${stems[i]} ${suffixes[i % suffixes.length]}`,
      tax_office: offices[i % offices.length],
      tax_number: String(1000000000 + i * 7654321).slice(0, 10),
      city: cities[i % cities.length],
      email: `muhasebe@${stems[i].toLowerCase().replace(/[^a-z]+/g, "")}.com.tr`,
      phone: `+90 2${int(12, 62)} ${int(200, 899)} ${int(1000, 9999)}`,
      payment_term_days: pick([0, 30, 45, 60, 90]),
      currency: pick(["TRY", "TRY", "TRY", "EUR", "USD"]),
      is_einvoice_user: rnd() > 0.3,
    };
    customers.push({ id: null, md });
  }

  const groups = [
    { n: "Celik Profil", c: "PRF", u: "MT", lo: 120, hi: 400 },
    { n: "Aluminyum Levha", c: "ALV", u: "M2", lo: 600, hi: 1600 },
    { n: "Hidrolik Silindir", c: "HID", u: "ADET", lo: 2500, hi: 9000 },
    { n: "Rulman", c: "RLM", u: "ADET", lo: 40, hi: 320 },
    { n: "Pnomatik Valf", c: "PNV", u: "ADET", lo: 300, hi: 1400 },
    { n: "Redüktör", c: "RDK", u: "ADET", lo: 4000, hi: 18000 },
    { n: "Zincir Dislisi", c: "ZND", u: "ADET", lo: 150, hi: 900 },
    { n: "Kaynak Teli", c: "KYT", u: "KG", lo: 90, hi: 260 },
    { n: "Paslanmaz Boru", c: "PSB", u: "MT", lo: 200, hi: 750 },
    { n: "Servo Motor", c: "SRV", u: "ADET", lo: 8000, hi: 32000 },
  ];
  const sizes = ["20x20", "30x30", "40x40", "50x50", "60x40", "80mm", "100mm", "6204", "6206", "2mm", "3mm", "5mm"];
  const products = [];
  for (let g = 0; g < groups.length; g++) {
    for (let k = 0; k < 4; k++) {
      const size = sizes[(g * 4 + k) % sizes.length];
      products.push({
        id: null,
        md: {
          title: `${groups[g].n} ${size}`,
          code: `${groups[g].c}-${String(1000 + g * 40 + k * 7)}`,
          unit: groups[g].u,
          list_price: money(int(groups[g].lo, groups[g].hi) + rnd()),
          vat_rate: 20,
          on_hand: int(0, 2400),
        },
      });
    }
  }

  for (const c of customers) {
    const r = await client.entities.create({ type: "customer", name: c.md.title, metadata: c.md });
    c.id = r?.entity?.id ?? r?.id;
  }
  for (const p of products) {
    const r = await client.entities.create({ type: "product", name: p.md.title, metadata: p.md });
    p.id = r?.entity?.id ?? p.id;
  }
  return {
    customers: customers.length,
    products: products.length,
    customer_ids: customers.slice(0, 3).map((c) => c.id),
    product_ids: products.slice(0, 3).map((p) => p.id),
  };
};

