// Documents on top of the master data: quotes, invoices (across the whole
// status lifecycle) and payments. Deterministic, and idempotent by document_no.
export default async (_ctx, client) => {
  let s = 7761;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const money = (n) => Math.round(n * 100) / 100;
  const pick = (a) => a[Math.floor(rnd() * a.length)];

  const cs = (await client.entities.list({ entity_type: "customer", limit: 500 })).entities ?? [];
  const ps = (await client.entities.list({ entity_type: "product", limit: 500 })).entities ?? [];
  if (cs.length < 5 || ps.length < 5) return { error: "seed masters first", cs: cs.length, ps: ps.length };

  const taken = new Set();
  for (const t of ["quote", "invoice", "payment"]) {
    const r = await client.entities.list({ entity_type: t, limit: 500 });
    for (const e of r.entities ?? []) taken.add(`${t}:${e.name}`);
  }

  const day = (offset) => {
    const base = Date.UTC(2026, 0, 5);
    return new Date(base + offset * 86400000).toISOString().slice(0, 10);
  };
  const buildLines = () => {
    const n = int(1, 6);
    const lines = [];
    for (let i = 0; i < n; i++) {
      const p = ps[Math.floor(rnd() * ps.length)];
      const qty = p.metadata.unit === "ADET" ? int(1, 25) : int(5, 400);
      const price = money(p.metadata.list_price * (0.9 + rnd() * 0.2));
      lines.push({
        product_id: p.id,
        description: p.metadata.title,
        quantity: qty,
        unit_price: price,
        vat_rate: 20,
        line_total: money(qty * price),
      });
    }
    const subtotal = money(lines.reduce((a, l) => a + l.line_total, 0));
    const vat_total = money(subtotal * 0.2);
    return { lines, subtotal, vat_total, grand_total: money(subtotal + vat_total) };
  };

  const out = { quotes: 0, invoices: 0, payments: 0 };
  const madeInvoices = [];

  for (let i = 1; i <= 55; i++) {
    const c = cs[Math.floor(rnd() * cs.length)];
    const d = int(0, 200);
    const t = buildLines();
    const document_no = `TEK2026${String(i).padStart(6, "0")}`;
    const name = `${document_no} - ${c.metadata.title}`;
    if (taken.has(`quote:${name}`)) continue;
    await client.entities.create({
      type: "quote", name,
      metadata: {
        document_no, status: pick(["draft", "sent", "sent", "accepted", "accepted", "rejected"]),
        date: day(d), valid_until: day(d + 30), customer_id: c.id,
        currency: c.metadata.currency ?? "TRY", ...t,
      },
    });
    out.quotes++;
  }

  for (let i = 1; i <= 85; i++) {
    const c = cs[Math.floor(rnd() * cs.length)];
    const d = int(0, 210);
    const t = buildLines();
    const status = pick(["draft", "issued", "posted", "posted", "posted", "cancelled"]);
    const document_no = `FTR2026${String(i).padStart(6, "0")}`;
    const name = `${document_no} - ${c.metadata.title}`;
    if (taken.has(`invoice:${name}`)) continue;
    await client.entities.create({
      type: "invoice", name,
      metadata: {
        document_no, status, date: day(d),
        due_date: day(d + (c.metadata.payment_term_days ?? 30)),
        customer_id: c.id, currency: c.metadata.currency ?? "TRY", fx_rate: 1,
        einvoice_uuid: c.metadata.is_einvoice_user && status === "posted"
          ? `GIB-${String(100000 + i * 37)}-${String(2026)}` : undefined,
        ...t,
      },
    });
    if (status === "posted") madeInvoices.push({ cid: c.id, total: t.grand_total, date: day(d), no: document_no });
    out.invoices++;
  }

  for (let i = 0; i < madeInvoices.length; i++) {
    if (rnd() > 0.75) continue; // some posted invoices stay open
    const inv = madeInvoices[i];
    const name = `TAH2026${String(i + 1).padStart(6, "0")} - ${inv.no}`;
    if (taken.has(`payment:${name}`)) continue;
    await client.entities.create({
      type: "payment", name,
      metadata: {
        date: inv.date, customer_id: inv.cid,
        amount: rnd() > 0.3 ? inv.total : money(inv.total * (0.3 + rnd() * 0.5)),
        currency: "TRY", method: pick(["BANKA", "BANKA", "KASA", "CEK", "SENET"]),
      },
    });
    out.payments++;
  }

  return out;
};

