// Turn the stored scalar references into real graph edges.
//
// Every edge below is DERIVED from data already on the document — nothing is
// invented. Documents whose scalar is absent are counted as unlinkable and
// reported, not guessed at.
export default async (_ctx, client) => {
  const load = async (t) =>
    (await client.entities.list({ entity_type: t, limit: 1000 })).entities ?? [];
  const [customers, products, quotes, invoices, payments] = await Promise.all([
    load("customer"), load("product"), load("quote"), load("invoice"), load("payment"),
  ]);
  const byId = new Map();
  for (const e of [...customers, ...products, ...quotes, ...invoices, ...payments]) byId.set(e.id, e);

  const stats = { linked: 0, skipped_missing_target: 0, failed: 0 };
  const errors = [];
  const link = async (from, to, slug, metadata) => {
    if (!from || !to || !byId.has(to)) { stats.skipped_missing_target++; return; }
    try {
      await client.entities.link({
        from_entity_id: from, to_entity_id: to,
        relationship_type_slug: slug, source: "api", metadata,
      });
      stats.linked++;
    } catch (e) {
      const m = String(e?.message ?? e);
      if (/already exists|duplicate/i.test(m)) return;
      stats.failed++;
      if (errors.length < 5) errors.push(`${slug}: ${m.slice(0, 120)}`);
    }
  };

  // Document -> customer, straight off the stored customer_id.
  for (const q of quotes) await link(q.id, q.metadata?.customer_id, "quote_customer");
  for (const i of invoices) await link(i.id, i.metadata?.customer_id, "invoice_customer");
  for (const p of payments) await link(p.id, p.metadata?.customer_id, "payment_customer");

  // Document -> product, one edge per DISTINCT product on the lines, carrying
  // the aggregated quantity and value so the edge answers "how much" directly.
  const linkLines = async (doc, slug) => {
    const agg = new Map();
    for (const l of doc.metadata?.lines ?? []) {
      if (!l?.product_id) continue;
      const cur = agg.get(l.product_id) ?? { quantity: 0, value: 0, lines: 0 };
      cur.quantity += Number(l.quantity) || 0;
      cur.value += Number(l.line_total) || 0;
      cur.lines += 1;
      agg.set(l.product_id, cur);
    }
    for (const [pid, a] of agg) {
      await link(doc.id, pid, slug, {
        quantity: Math.round(a.quantity * 100) / 100,
        line_total: Math.round(a.value * 100) / 100,
        line_count: a.lines,
      });
    }
  };
  for (const q of quotes) await linkLines(q, "document_product");
  for (const i of invoices) await linkLines(i, "document_product");

  // Chain edges, only where the scalar is actually present.
  for (const i of invoices) if (i.metadata?.quote_id) await link(i.id, i.metadata.quote_id, "invoice_from_quote");
  for (const p of payments) if (p.metadata?.invoice_id) await link(p.id, p.metadata.invoice_id, "payment_invoice");

  return {
    ...stats,
    errors,
    chain_gaps: {
      invoices_without_quote_id: invoices.filter((i) => !i.metadata?.quote_id).length,
      payments_without_invoice_id: payments.filter((p) => !p.metadata?.invoice_id).length,
    },
  };
};

