// Turn the stored scalar references into real graph edges.
//
// Every edge is DERIVED from data already on the document — nothing is invented.
// The sandbox caps a script at 200 SDK calls, so this finds only the edges that
// are still MISSING (one SQL call) and writes up to BUDGET of them. Re-run until
// `remaining` is 0.
const BUDGET = 180;

export default async (_ctx, client) => {
  // Documents whose customer/product edge does not exist yet. One query, so the
  // call budget goes almost entirely to writes.
  const missing = await client.query(`
    WITH doc AS (
      SELECT e.id,
             et.slug AS type,
             (e.metadata->>'customer_id')::bigint AS customer_id,
             e.metadata->'lines' AS lines
      FROM entities e
      JOIN entity_types et ON et.id = e.entity_type_id
      WHERE e.deleted_at IS NULL
        AND et.slug IN ('quote','invoice','payment')
    ),
    want AS (
      SELECT id AS from_id, customer_id AS to_id,
             CASE type WHEN 'quote' THEN 'quote_customer'
                       WHEN 'invoice' THEN 'invoice_customer'
                       ELSE 'payment_customer' END AS slug,
             NULL::numeric AS quantity, NULL::numeric AS line_total, NULL::int AS line_count
      FROM doc WHERE customer_id IS NOT NULL
      UNION ALL
      SELECT d.id,
             (l->>'product_id')::bigint,
             'document_product',
             SUM((l->>'quantity')::numeric),
             SUM((l->>'line_total')::numeric),
             COUNT(*)::int
      FROM doc d, jsonb_array_elements(COALESCE(d.lines,'[]'::jsonb)) l
      WHERE d.type IN ('quote','invoice') AND l->>'product_id' IS NOT NULL
      GROUP BY d.id, (l->>'product_id')::bigint
    )
    SELECT w.from_id, w.to_id, w.slug, w.quantity, w.line_total, w.line_count
    FROM want w
    JOIN entity_relationship_types rt ON rt.slug = w.slug AND rt.status = 'active'
    LEFT JOIN entity_relationships r
      ON r.from_entity_id = w.from_id
     AND r.to_entity_id = w.to_id
     AND r.relationship_type_id = rt.id
     AND r.deleted_at IS NULL
    WHERE r.id IS NULL
    ORDER BY w.slug, w.from_id
  `);
  const rows = missing?.rows ?? missing ?? [];
  const batch = rows.slice(0, BUDGET);

  let linked = 0;
  let failed = 0;
  const errors = [];
  for (const r of batch) {
    try {
      await client.entities.link({
        from_entity_id: Number(r.from_id),
        to_entity_id: Number(r.to_id),
        relationship_type_slug: r.slug,
        source: "api",
        metadata: r.slug === "document_product"
          ? {
              quantity: Number(r.quantity),
              line_total: Number(r.line_total),
              line_count: Number(r.line_count),
            }
          : undefined,
      });
      linked++;
    } catch (e) {
      failed++;
      if (errors.length < 3) errors.push(String(e?.message ?? e).slice(0, 140));
    }
  }
  return { linked, failed, errors, remaining: Math.max(0, rows.length - batch.length) };
};

