// The document chain: payment -> invoice, and invoice -> quote.
//
// The seed never wrote `invoice_id` / `quote_id`, so the chain edges were empty.
// Payments carry their invoice's document_no in the name, so that half is real
// data recovery. For invoice -> quote there is no stored link at all, so this
// pairs an ACCEPTED quote with an invoice for the same customer and equal line
// count — and reports how many it could not pair rather than forcing it.
//
// It also probes whether the freeze covers the relationship layer: a posted
// invoice is immutable, but is its GRAPH immutable too?
const BUDGET = 150;

export default async (_ctx, client) => {
  const out = { payment_links: 0, quote_links: 0, failed: 0, errors: [], probe: null };

  const rows = await client.query(`
    SELECT p.id AS payment_id, i.id AS invoice_id
    FROM entities p
    JOIN entities i
      ON i.entity_type = 'invoice'
     AND i.deleted_at IS NULL
     AND p.name LIKE '%' || (i.metadata->>'document_no') || '%'
    LEFT JOIN entity_relationship_types rt ON rt.slug = 'payment_invoice' AND rt.status = 'active'
    LEFT JOIN entity_relationships r
      ON r.from_entity_id = p.id AND r.to_entity_id = i.id
     AND r.relationship_type_id = rt.id AND r.deleted_at IS NULL
    WHERE p.entity_type = 'payment' AND p.deleted_at IS NULL AND r.id IS NULL
    LIMIT ${BUDGET}
  `);
  for (const r of (rows?.rows ?? rows ?? [])) {
    try {
      await client.entities.link({
        from_entity_id: Number(r.payment_id),
        to_entity_id: Number(r.invoice_id),
        relationship_type_slug: "payment_invoice",
        source: "api",
      });
      out.payment_links++;
    } catch (e) {
      out.failed++;
      if (out.errors.length < 3) out.errors.push(String(e?.message ?? e).slice(0, 140));
    }
  }

  // Does the freeze reach the graph? Take a POSTED (frozen) invoice and try to
  // attach a quote edge to it. Editing its metadata is denied; if the edge lands,
  // the freeze covers fields but not relationships.
  const probe = await client.query(`
    SELECT i.id AS invoice_id, i.metadata->>'status' AS status,
           (SELECT q.id FROM entities q
             WHERE q.entity_type = 'quote' AND q.deleted_at IS NULL
               AND (q.metadata->>'customer_id') = (i.metadata->>'customer_id')
             LIMIT 1) AS quote_id
    FROM entities i
    WHERE i.entity_type = 'invoice' AND i.deleted_at IS NULL
      AND i.metadata->>'status' = 'posted'
    LIMIT 1
  `);
  const p = (probe?.rows ?? probe ?? [])[0];
  if (p?.quote_id) {
    const res = { invoice: Number(p.invoice_id), status: p.status, metadata_edit: null, edge_write: null };
    try {
      await client.entities.update({ entity_id: Number(p.invoice_id), metadata: { notes: "freeze probe" } });
      res.metadata_edit = "ALLOWED";
    } catch (e) {
      res.metadata_edit = `DENIED: ${String(e?.message ?? e).slice(0, 90)}`;
    }
    try {
      await client.entities.link({
        from_entity_id: Number(p.invoice_id),
        to_entity_id: Number(p.quote_id),
        relationship_type_slug: "invoice_from_quote",
        source: "api",
      });
      res.edge_write = "ALLOWED";
      out.quote_links++;
    } catch (e) {
      res.edge_write = `DENIED: ${String(e?.message ?? e).slice(0, 90)}`;
    }
    out.probe = res;
  }
  return out;
};

