// Does the freeze now cover the GRAPH?
//
// Before the edge paths were gated, a posted invoice's metadata was sealed while
// `entity_relationships` stayed wide open: metadata_edit DENIED, edge_write
// ALLOWED. This re-runs that exact probe against the live server.
export default async (_ctx, client) => {
  const probe = await client.query(`
    SELECT i.id AS invoice_id, i.metadata->>'status' AS status,
           (SELECT q.id FROM entities q
             WHERE q.entity_type = 'quote' AND q.deleted_at IS NULL
             LIMIT 1) AS quote_id
    FROM entities i
    WHERE i.entity_type = 'invoice' AND i.deleted_at IS NULL
      AND i.metadata->>'status' = 'posted'
    LIMIT 1
  `);
  const p = (probe?.rows ?? probe ?? [])[0];
  if (!p?.quote_id) return { error: "no posted invoice / quote to probe" };

  const out = { invoice: Number(p.invoice_id), status: p.status };

  try {
    await client.entities.update({
      entity_id: Number(p.invoice_id),
      metadata: { notes: "freeze probe" },
    });
    out.metadata_edit = "ALLOWED";
  } catch (e) {
    out.metadata_edit = `DENIED: ${String(e?.message ?? e).slice(0, 100)}`;
  }

  try {
    await client.entities.link({
      from_entity_id: Number(p.invoice_id),
      to_entity_id: Number(p.quote_id),
      relationship_type_slug: "invoice_from_quote",
      source: "api",
    });
    out.edge_write = "ALLOWED";
  } catch (e) {
    out.edge_write = `DENIED: ${String(e?.message ?? e).slice(0, 100)}`;
  }

  return out;
};

