// Give products real designations.
//
// The first generator crossed every product group against ONE shared size list,
// so it emitted "Servo Motor 30x30" and "Redüktör 5mm" — sizes that belong to
// steel profile and sheet, not to motors and gearboxes. Each group now carries
// the designation its own trade actually uses (bearing numbers, DIN pipe sizes,
// gearbox ratios, motor power), which also makes the demo legible to someone who
// knows the domain.
const SIZES = {
  "Celik Profil": ["20x20", "30x30", "40x40", "50x50"],
  "Aluminyum Levha": ["2mm", "3mm", "5mm", "8mm"],
  "Hidrolik Silindir": ["40/25-200", "50/30-300", "63/35-400", "80/45-500"],
  Rulman: ["6204-2RS", "6205-2RS", "6206-2RS", "6208-2RS"],
  "Pnomatik Valf": ['3/2 1/8"', '5/2 1/4"', '5/3 1/4"', '5/2 1/2"'],
  "Redüktör": ["i=10", "i=20", "i=40", "i=60"],
  "Zincir Dislisi": ["08B-1 Z15", "08B-1 Z25", "10B-1 Z17", "12B-1 Z19"],
  "Kaynak Teli": ["SG2 0.8mm", "SG2 1.0mm", "SG2 1.2mm", "E308L 2.5mm"],
  "Paslanmaz Boru": ["304 DN25", "304 DN50", "316L DN25", "316L DN80"],
  "Servo Motor": ["0.4kW", "0.75kW", "1.5kW", "3.0kW"],
};

export default async (_ctx, client) => {
  const res = await client.entities.list({ entity_type: "product", limit: 500 });
  const products = res.entities ?? [];

  // Bucket by group, ordered by stock code so the assignment is stable across
  // re-runs (the code carries the original group/index and never changes).
  const byGroup = new Map();
  for (const p of products) {
    const group = Object.keys(SIZES).find((g) => String(p.metadata?.title ?? "").startsWith(g));
    if (!group) continue;
    if (!byGroup.has(group)) byGroup.set(group, []);
    byGroup.get(group).push(p);
  }

  const out = { renamed: 0, unchanged: 0, skipped: products.length, errors: [] };
  for (const [group, list] of byGroup) {
    out.skipped -= list.length;
    list.sort((a, b) => String(a.metadata?.code ?? "").localeCompare(String(b.metadata?.code ?? "")));
    for (let i = 0; i < list.length; i++) {
      const p = list[i];
      const title = `${group} ${SIZES[group][i % SIZES[group].length]}`;
      if (p.name === title && p.metadata?.title === title) {
        out.unchanged++;
        continue;
      }
      try {
        await client.entities.update({ entity_id: p.id, name: title, metadata: { title } });
        out.renamed++;
      } catch (e) {
        if (out.errors.length < 3) out.errors.push(String(e?.message ?? e).slice(0, 140));
      }
    }
  }
  return out;
};

// Give the three leftover products real designations.
//
// The bulk rename assigned each group its own trade designation list. Three rows
// survive from the very first hand-written seed and sit OUTSIDE that list — their
// codes were hand-picked (PRF-4040, RLM-6204), so index-based assignment collides
// with an already-renamed sibling on the unique-slug constraint. They are keyed
// by stock code here and given the next real designation in their own series.
const BY_CODE = {
  "ALV-1040": "Aluminyum Levha 10mm",
  "HID-1101": "Hidrolik Silindir 100/56-600",
  "RLM-6204": "Rulman 6210-2RS",
};

export default async (_ctx, client) => {
  const res = await client.entities.list({ entity_type: "product", limit: 500 });
  const out = { renamed: 0, unchanged: 0, missing: [], errors: [] };

  for (const [code, title] of Object.entries(BY_CODE)) {
    const p = (res.entities ?? []).find((e) => e.metadata?.code === code);
    if (!p) {
      out.missing.push(code);
      continue;
    }
    if (p.name === title && p.metadata?.title === title) {
      out.unchanged++;
      continue;
    }
    try {
      await client.entities.update({ entity_id: p.id, name: title, metadata: { title } });
      out.renamed++;
    } catch (e) {
      out.errors.push(`${code}: ${String(e?.message ?? e).slice(0, 120)}`);
    }
  }
  return out;
};

