// Seed the document chain as an actual chain: Teklif -> Fatura -> Tahsilat.
//
// The earlier seed generated each document type independently, so no invoice
// ever knew which quote it came from and `invoice_from_quote` stayed empty. Here
// one chain is built end to end from a single set of lines, and BOTH layers are
// written: the scalar (`quote_id` / `invoice_id`, which is what the document
// stores and validates) and the graph edge (which is what makes it traversable).
//
// Ordering is forced by the freeze. `invoice` declares x-transitions with
// frozen_from "issued", and relationship writes are now gated the same way as
// fields, so every edge must land while the invoice is still a draft. The
// sequence create-draft -> link -> issued -> posted is therefore not a style
// choice; issuing first would make the document unlinkable.
//
// Numbered in the 2027 series so this set is distinguishable from the unchained
// 2026 documents still in the database.
//
// The sandbox caps a script at 200 SDK calls and one chain costs up to ~18, so
// this only starts a chain it can finish and reports `remaining`. Re-run until 0.
const TARGET_CHAINS = 40;
const BUDGET = 185;
const PER_CHAIN_WORST_CASE = 20;

export default async (_ctx, client) => {
  let s = 991733;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const money = (n) => Math.round(n * 100) / 100;
  const day = (o) => new Date(Date.UTC(2027, 0, 4) + o * 86400000).toISOString().slice(0, 10);

  let calls = 0;
  const spend = (n) => {
    calls += n;
  };

  const cs = (await client.entities.list({ entity_type: "customer", limit: 500 })).entities ?? [];
  const ps = (await client.entities.list({ entity_type: "product", limit: 500 })).entities ?? [];
  spend(2);
  if (cs.length < 5 || ps.length < 5) return { error: "seed masters first" };

  // Which chains already exist, so a re-run resumes instead of duplicating.
  const done = await client.query(`
    SELECT metadata->>'document_no' AS no FROM entities
    WHERE entity_type = 'quote' AND deleted_at IS NULL
      AND metadata->>'document_no' LIKE 'TEK2027%'
  `);
  spend(1);
  const built = new Set((done?.rows ?? done ?? []).map((r) => String(r.no)));

  const out = { chains: 0, quotes: 0, invoices: 0, payments: 0, edges: 0, errors: [], remaining: 0 };
  const note = (e) => {
    if (out.errors.length < 4) out.errors.push(String(e?.message ?? e).slice(0, 150));
  };

  const link = async (from, to, slug, metadata) => {
    await client.entities.link({
      from_entity_id: from,
      to_entity_id: to,
      relationship_type_slug: slug,
      source: "api",
      metadata,
    });
    spend(1);
    out.edges++;
  };

  let pending = 0;
  for (let i = 1; i <= TARGET_CHAINS; i++) {
    const quoteNo = `TEK2027${String(i).padStart(6, "0")}`;
    if (built.has(quoteNo)) continue;
    if (calls + PER_CHAIN_WORST_CASE > BUDGET) {
      pending++;
      continue;
    }

    const c = cs[int(0, cs.length - 1)];
    const d = int(0, 300);

    // Distinct products per document, so one product is one line and one edge.
    const pool = [...ps];
    const lines = [];
    const n = int(2, 4);
    for (let k = 0; k < n; k++) {
      const p = pool.splice(int(0, pool.length - 1), 1)[0];
      const qty = p.metadata.unit === "ADET" ? int(1, 20) : int(5, 300);
      const price = money(p.metadata.list_price * (0.9 + rnd() * 0.2));
      lines.push({
        product_id: p.id,
        description: p.metadata.title,
        quantity: qty,
        unit_price: price,
        vat_rate: 20,
        line_total: money(qty * price),
      });
    }
    const subtotal = money(lines.reduce((a, l) => a + l.line_total, 0));
    const vat_total = money(subtotal * 0.2);
    const totals = { lines, subtotal, vat_total, grand_total: money(subtotal + vat_total) };

    const roll = rnd();
    const quoteStatus = roll < 0.6 ? "accepted" : roll < 0.85 ? "sent" : "rejected";
    const currency = c.metadata.currency ?? "TRY";

    try {
      // --- Teklif -------------------------------------------------------
      // Quote declares no transition rule, so its final status is set at create.
      const q = await client.entities.create({
        type: "quote",
        name: `${quoteNo} - ${c.metadata.title}`,
        metadata: {
          document_no: quoteNo,
          status: quoteStatus,
          date: day(d),
          valid_until: day(d + 30),
          customer_id: c.id,
          currency,
          ...totals,
        },
      });
      spend(1);
      const quoteId = Number(q.entity.id);
      out.quotes++;

      await link(quoteId, c.id, "quote_customer");
      for (const l of lines) {
        await link(quoteId, l.product_id, "document_product", {
          quantity: l.quantity,
          line_total: l.line_total,
          line_count: 1,
        });
      }

      if (quoteStatus !== "accepted") {
        out.chains++;
        continue;
      }

      // --- Fatura -------------------------------------------------------
      // Created as a DRAFT on purpose: every edge below has to land before the
      // invoice is issued, because issuing freezes fields and graph alike.
      const invoiceNo = `FTR2027${String(i).padStart(6, "0")}`;
      const inv = await client.entities.create({
        type: "invoice",
        name: `${invoiceNo} - ${c.metadata.title}`,
        metadata: {
          document_no: invoiceNo,
          status: "draft",
          date: day(d + int(3, 20)),
          due_date: day(d + 20 + (c.metadata.payment_term_days ?? 30)),
          customer_id: c.id,
          quote_id: quoteId,
          currency,
          fx_rate: 1,
          ...totals,
        },
      });
      spend(1);
      const invoiceId = Number(inv.entity.id);
      out.invoices++;

      await link(invoiceId, c.id, "invoice_customer");
      await link(invoiceId, quoteId, "invoice_from_quote");
      for (const l of lines) {
        await link(invoiceId, l.product_id, "document_product", {
          quantity: l.quantity,
          line_total: l.line_total,
          line_count: 1,
        });
      }

      // Now advance it along the declared transitions. draft -> issued -> posted.
      await client.entities.update({ entity_id: invoiceId, metadata: { status: "issued" } });
      spend(1);

      const posted = rnd() < 0.75;
      if (!posted) {
        out.chains++;
        continue;
      }
      await client.entities.update({
        entity_id: invoiceId,
        metadata: {
          status: "posted",
          einvoice_uuid: c.metadata.is_einvoice_user ? `GIB-${200000 + i * 41}-2027` : undefined,
        },
      });
      spend(1);

      // --- Tahsilat -----------------------------------------------------
      // The payment points AT a posted invoice. That direction stays open by
      // design: being referenced is not a mutation of the frozen document.
      if (rnd() < 0.7) {
        const payNo = `TAH2027${String(i).padStart(6, "0")}`;
        const full = rnd() < 0.7;
        const pay = await client.entities.create({
          type: "payment",
          name: `${payNo} - ${invoiceNo}`,
          metadata: {
            date: day(d + int(25, 70)),
            customer_id: c.id,
            invoice_id: invoiceId,
            amount: full ? totals.grand_total : money(totals.grand_total * (0.3 + rnd() * 0.4)),
            currency,
            method: ["BANKA", "BANKA", "KASA", "CEK", "SENET"][int(0, 4)],
          },
        });
        spend(1);
        const paymentId = Number(pay.entity.id);
        out.payments++;

        await link(paymentId, c.id, "payment_customer");
        await link(paymentId, invoiceId, "payment_invoice");
      }

      out.chains++;
    } catch (e) {
      note(e);
    }
  }

  out.remaining = pending;
  out.calls_used = calls;
  return out;
};

