// Does the freeze cover the GRAPH, not just the fields?
//
// Takes a POSTED (frozen) invoice from the 2027 chain and tries both a metadata
// edit and an edge write. Before the edge paths were gated the second one
// succeeded, so a legally frozen invoice could be re-pointed at another quote.
export default async (_ctx, client) => {
  const probe = await client.query(`
    SELECT i.id AS invoice_id, i.name, i.metadata->>'status' AS status,
           (SELECT q.id FROM entities q
             WHERE q.entity_type = 'quote' AND q.deleted_at IS NULL
               AND q.metadata->>'document_no' LIKE 'TEK2027%'
             ORDER BY q.id DESC LIMIT 1) AS quote_id
    FROM entities i
    WHERE i.entity_type = 'invoice' AND i.deleted_at IS NULL
      AND i.metadata->>'status' = 'posted'
      AND i.metadata->>'document_no' LIKE 'FTR2027%'
    ORDER BY i.id LIMIT 1
  `);
  const p = (probe?.rows ?? probe ?? [])[0];
  if (!p?.quote_id) return { error: "no posted 2027 invoice to probe" };

  const out = { invoice: Number(p.invoice_id), name: p.name, status: p.status };

  try {
    await client.entities.update({
      entity_id: Number(p.invoice_id),
      metadata: { notes: "freeze probe" },
    });
    out.metadata_edit = "ALLOWED";
  } catch (e) {
    out.metadata_edit = `DENIED: ${String(e?.message ?? e).slice(0, 90)}`;
  }

  try {
    await client.entities.link({
      from_entity_id: Number(p.invoice_id),
      to_entity_id: Number(p.quote_id),
      relationship_type_slug: "invoice_from_quote",
      source: "api",
    });
    out.edge_write = "ALLOWED";
  } catch (e) {
    out.edge_write = `DENIED: ${String(e?.message ?? e).slice(0, 90)}`;
  }

  return out;
};

