 * token, so an inbound URL like `/<org>/$member/<slug>` resolves the type
 * segment to `undefined` and renders "Not Found". In-app links already encode
 * the leading `$` (see `encodeEntityType`), but the browser address bar shows /
 * copies the DECODED form, so hard loads of a pasted, bookmarked, or shared
 * member-entity URL arrive with the literal `$`. Canonicalizing inbound paths
 * here closes that gap — encode-on-generate is otherwise not symmetric with
 * what the URL bar hands back. No legitimate route segment begins with a
 * literal `$`, so this only ever rescues the entity-type case.
 */
export function reencodeLiteralEntityTypePath(pathname: string): string {
	if (!pathname.includes("/$")) return pathname;
	return pathname
		.split("/")
		.map((segment) =>
			segment.startsWith("$") ? `%24${segment.slice(1)}` : segment,
		)
		.join("/");
}

export function buildEntityTypeListPath(
	owner: string,
	entityType: string,
): string {
	return `/${owner}/${encodeEntityType(entityType)}`;
}

function buildEntityPath(segments: EntityPathSegment[]): string {
	return segments
		.map(
			(segment) => `${encodeEntityType(segment.entity_type)}/${segment.slug}`,
		)
		.join("/");
}

export function buildEntityUrl(
	owner: string,
	segments: EntityPathSegment[],
): string {
	const suffix = buildEntityPath(segments);
	return suffix ? `/${owner}/${suffix}` : `/${owner}`;
}

export function parseEntityPath(path: string): {
	owner: string | null;
	ownerInfo: ParsedOwner | null;
	segments: EntityPathSegment[];
	isValid: boolean;
} {
	const normalized = normalizePath(path);
	const parts = normalized
		.replace(/^\/+|\/+$/g, "")
		.split("/")
		.filter(Boolean);

