/**
 * Format a single scalar per an explicit directive.
 *
 * `format` omitted or `"text"` = raw passthrough (`String(value)`) — this is the
 * safe default so existing bindings never silently reformat. `"auto"` opts into
 * shape inference (dates/urls, never currency). Specific formats force that
 * treatment. Booleans always render Yes/No; non-scalars are JSON-stringified.
 */
export function formatValue(value: unknown, format?: ValueFormat): string {
	if (value === null || value === undefined) return "";

	if (typeof value === "boolean") return value ? "Yes" : "No";

	if (typeof value === "number") {
		if (format === "currency") return formatCurrency(value);
		if (format === undefined || format === "text") return String(value);
		return formatNumber(value);
	}

	if (typeof value !== "string") return formatStructuredValue(value);

	switch (format) {
		case "currency":
			return formatCurrency(Number(value));
		case "date":
			return formatDate(value);
		case "url":
			return formatUrlLabel(value);
		case "enum":
			return humanizeToken(value);
		case "number":
			return formatNumber(Number(value));
		case "auto": {
			// Infer date/url from the value's shape (the table's prior auto
			// behavior), but never currency.
			if (isHttpUrl(value)) return formatUrlLabel(value);
			if (looksLikeDateString(value)) return formatDate(value);
			return value;
		}
		default:
			// undefined | "text" → raw passthrough (no silent reformatting).
			return value;
	}
}

