export interface ChannelAboutMetadata {
	connection_id: string;
	channel_key: string;
	/**
	 * Every writer currently asserting this edge. Config and manual both target
	 * the same (channel, business entity) triple, and the live-triple unique
	 * index excludes `source`, so one row has to carry both assertions or one
	 * writer silently revokes the other's. `source` remains whoever created the
	 * row; `owners` is who still wants it.
	 */
	owners?: string[];
}

/**
 * Owners of an existing row, tolerating rows written before `owners` existed:
 * those carry a single assertion, identified by `source`. Used in SQL and in
 * TS so both sides read a pre-`owners` row the same way — no backfill needed.
 */
const OWNERS_SQL = "COALESCE(r.metadata->'owners', jsonb_build_array(r.source))";

function ownersOf(row: {
	owners: string[] | null;
	source: string | null;
}): string[] {
	if (row.owners && row.owners.length > 0) return row.owners;
	return row.source ? [row.source] : [];
}

	const metadata: ChannelAboutMetadata = {
		...opts.metadata,
		owners: [opts.source],
	};
	// `source` is deliberately NOT overwritten on conflict: it records who
	// created the row, and rewriting it handed ownership to whoever wrote last
	// while each sweep only ever looks for its own source — so a config sync
	// could capture a user's manual link and then reconcile it away, and a
	// manual write could strand a config edge beyond config's reach.
	await opts.sql`
    INSERT INTO entity_relationships (
      organization_id, from_entity_id, to_entity_id, relationship_type_id,
      metadata, confidence, source, created_by, updated_by, created_at, updated_at
    ) VALUES (
      ${opts.organizationId}, ${opts.fromChannelEntityId}, ${opts.toBusinessEntityId},
      ${opts.typeId}, ${opts.sql.json(metadata)}, 1.0, ${opts.source},
      ${opts.userId ?? null}, ${opts.userId ?? null},
      current_timestamp, current_timestamp
    )
    ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
      WHERE deleted_at IS NULL
    DO UPDATE SET
      metadata = EXCLUDED.metadata || jsonb_build_object(
        'owners',
        (
          SELECT jsonb_agg(DISTINCT owner)
          FROM jsonb_array_elements_text(
            CASE
              WHEN entity_relationships.deleted_at IS NULL
                THEN COALESCE(
                  entity_relationships.metadata->'owners',
                  jsonb_build_array(entity_relationships.source)
                )
              ELSE '[]'::jsonb
            END || to_jsonb(${opts.source}::text)
          ) AS owner
        )
      ),
      updated_by = EXCLUDED.updated_by,
      updated_at = current_timestamp,
      deleted_at = NULL
  `;
}

/**
 * Withdraw one writer's assertion from an edge, tombstoning only once no
 * writer is left. Returns true when the edge was actually removed.
 */
async function retractAboutAssertion(opts: {
	id: number;
	owner: string;
	owners: string[];
	sql: DbClient;
}): Promise<boolean> {
	const remaining = opts.owners.filter((o) => o !== opts.owner);
	if (remaining.length > 0) {
		await opts.sql`
      UPDATE entity_relationships
      SET metadata = metadata || jsonb_build_object('owners', ${opts.sql.json(remaining)}),
          updated_at = current_timestamp
      WHERE id = ${opts.id}
    `;
		return false;
	}
	await opts.sql`
    UPDATE entity_relationships
    SET deleted_at = current_timestamp, updated_at = current_timestamp
    WHERE id = ${opts.id}
  `;
	return true;
}

