/**
 * UI-proof harness for the entity form (owletto#844).
 *
 * Renders `DynamicSchemaForm` against one fixed schema that exercises the three
 * things #844 adds — an array-of-object property, `x-link-entity-type`, and the
 * date/date-time formats — so the before/after shots differ only by the
 * component under test. Ephemeral: this file and `entity-form-proof.html` are
 * deleted once the proof is captured.
 */

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { useState } from "react";
import ReactDOM from "react-dom/client";
import { DynamicSchemaForm } from "./components/dynamic-schema-form";
import "./index.css";

const queryClient = new QueryClient({
	defaultOptions: { queries: { retry: false, refetchOnWindowFocus: false } },
});

const SCHEMA = {
	type: "object",
	required: ["invoice_no", "customer"],
	properties: {
		invoice_no: { type: "string", description: "Invoice No" },
		customer: {
			type: "string",
			description: "Customer",
			"x-link-entity-type": "company",
			"x-link-lookup-field": "slug",
		},
		issued_on: { type: "string", format: "date", description: "Issued On" },
		due_at: { type: "string", format: "date-time", description: "Due At" },
		vat_rate: { type: "number", enum: [0, 1, 10, 20], description: "VAT Rate" },
		lines: {
			type: "array",
			description: "Line Items",
			items: {
				type: "object",
				properties: {
					product: { type: "string", description: "Product" },
					qty: { type: "number", description: "Qty" },
					unit_price: { type: "number", description: "Unit Price" },
				},
			},
		},
	},
};

const INITIAL = {
	invoice_no: "INV-2026-0417",
	issued_on: "2026-03-31",
	vat_rate: 20,
	lines: [
		{ product: "Hydraulic press frame", qty: 2, unit_price: 4150 },
		{ product: "Bearing set 6204-2RS", qty: 48, unit_price: 3.2 },
	],
};

function Harness() {
	const [values, setValues] = useState<Record<string, unknown>>({});
	return (
		<div style={{ maxWidth: 720, margin: "0 auto", padding: "32px 24px" }}>
			<h1
				style={{ fontSize: 20, fontWeight: 600, margin: "0 0 4px" }}
				id="entity-form-proof"
			>
				Invoice
			</h1>
			<p
				style={{ fontSize: 13, opacity: 0.65, margin: "0 0 24px" }}
				data-testid="proof-caption"
			>
				Schema-driven entity form
			</p>
			<DynamicSchemaForm
				schema={SCHEMA}
				initialValues={INITIAL}
				onValuesChange={setValues}
				orgContext={{ organizationId: null, slug: "buremba" }}
			/>
			<pre
				data-testid="proof-values"
				style={{
					marginTop: 28,
					fontSize: 11,
					lineHeight: 1.5,
					opacity: 0.7,
					whiteSpace: "pre-wrap",
				}}
			>
				{JSON.stringify(values, null, 2)}
			</pre>
		</div>
	);
}

ReactDOM.createRoot(document.getElementById("root") as HTMLElement).render(
	<QueryClientProvider client={queryClient}>
		<Harness />
	</QueryClientProvider>,
);

/**
 * Capture one arm of the entity-form UI proof.
 *   node capture.mjs <label>
 * Asserts on the DOM first and prints a short report; the screenshot is a
 * by-product, so a silent blank page can never pass as a valid "before".
 */
import { chromium } from "/Users/burakemre/Code/lobu/node_modules/playwright/index.mjs";

const label = process.argv[2];
if (!label) throw new Error("usage: capture.mjs <label>");
const OUT = `/private/tmp/claude-501/-Users-burakemre-Code-lobu/f0b3eac6-8946-4c9e-bbf8-24d856a5592a/scratchpad/shot-${label}.png`;

const browser = await chromium.launch({
  executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
});
const page = await browser.newPage({ viewport: { width: 900, height: 1200 }, deviceScaleFactor: 2 });

const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });

await page.goto("http://localhost:5211/entity-form-proof.html", { waitUntil: "domcontentloaded" });
await page.waitForSelector("#entity-form-proof", { timeout: 20000 });
await page.waitForTimeout(2500);

const report = await page.evaluate(() => {
  const root = document.getElementById("root");
  const text = root?.innerText ?? "";
  const table = document.querySelector("table");
  const headerCells = table ? [...table.querySelectorAll("thead th")].map((c) => c.innerText.trim()).filter(Boolean) : [];
  const bodyRows = table ? table.querySelectorAll("tbody tr").length : 0;
  const inputsInTable = table ? table.querySelectorAll("input").length : 0;
  // A textarea/JSON blob is how the OLD form rendered an array-of-object prop.
  const textareas = root ? root.querySelectorAll("textarea").length : 0;
  const comboboxes = root ? root.querySelectorAll('[role="combobox"]').length : 0;
  const buttons = root ? [...root.querySelectorAll("button")].map((b) => b.innerText.trim()).filter(Boolean) : [];
  return {
    renderedChars: text.length,
    hasGridTable: Boolean(table),
    headerCells,
    bodyRows,
    inputsInTable,
    textareas,
    comboboxes,
    hasAddRow: buttons.some((b) => /add row/i.test(b)),
    dateButtons: buttons.filter((b) => /Mar|Pick a date/i.test(b)),
    mentionsLineItems: /Line Items/i.test(text),
    showsRawJsonBlob: /\[\{"product"|\[\s*\{\s*"product"/.test(text),
  };
});

console.log(`--- ${label} ---`);
console.log(JSON.stringify(report, null, 2));
console.log("pageErrors:", errors.length ? errors.slice(0, 4) : "none");

await page.screenshot({ path: OUT, fullPage: true });
console.log("shot:", OUT);
await browser.close();

