/**
 * Regressions introduced by the line-item grid PR (owletto#844), each found by
 * review and reproduced here before being fixed.
 *
 * All three share a shape: the new code is correct for the case the feature was
 * demoed with (string foreign key, UTC-or-east timezone, every required field
 * edited) and wrong for the neighbouring case.
 */

import { render } from "@testing-library/react";
// @ts-expect-error jsdom is available in the workspace without bundled types here.
import { JSDOM } from "jsdom";
import { describe, expect, it, vi } from "vitest";
import { DynamicSchemaForm } from "./dynamic-schema-form";
import { buildMetadataPatch } from "./entity-tabs";

const dom = new JSDOM("<!doctype html><html><body></body></html>", {
	url: "http://localhost",
});

globalThis.window = dom.window as unknown as Window & typeof globalThis;
globalThis.document = dom.window.document;
globalThis.navigator = dom.window.navigator;
globalThis.HTMLElement = dom.window.HTMLElement;
globalThis.Node = dom.window.Node;
globalThis.Element = dom.window.Element;
globalThis.MutationObserver = dom.window.MutationObserver;
globalThis.getComputedStyle = dom.window.getComputedStyle.bind(dom.window);

const proto = Element.prototype as unknown as Record<string, unknown>;
proto.hasPointerCapture ??= () => false;
proto.setPointerCapture ??= () => {};
proto.releasePointerCapture ??= () => {};

describe("buildMetadataPatch", () => {
	/**
	 * The server validates the PATCH as a document in its own right, not the
	 * merge of patch and stored row, so a patch that omits an unchanged required
	 * field fails schema validation. #844 narrowed the payload from "the whole
	 * cleaned object" to "only changed keys", which breaks every edit on a type
	 * that declares `required`.
	 */
	it("keeps unchanged keys so a required field never goes missing", () => {
		const patch = buildMetadataPatch(
			{ invoice_no: "INV-2", customer: "acme" },
			{ invoice_no: "INV-1", customer: "acme" },
		);
		expect(patch).toEqual({ invoice_no: "INV-2", customer: "acme" });
	});

	it("still sends an explicit null for a cleared key", () => {
		const patch = buildMetadataPatch(
			{ invoice_no: "INV-1" },
			{ invoice_no: "INV-1", note: "old" },
		);
		expect(patch).toEqual({ invoice_no: "INV-1", note: null });
	});

	it("stays undefined when nothing changed, so a name-only edit sends no metadata", () => {
		expect(
			buildMetadataPatch({ invoice_no: "INV-1" }, { invoice_no: "INV-1" }),
		).toBeUndefined();
	});
});

describe("linked-entity dispatch", () => {
	/**
	 * `x-link-entity-type` was checked AFTER the scalar `type` branches, so an
	 * integer foreign key — the common case in an imported relational system —
	 * rendered a bare number input and the picker never appeared.
	 */
	it("renders the picker for an integer foreign key, not a number input", () => {
		const view = render(
			<DynamicSchemaForm
				schema={{
					type: "object",
					properties: {
						customer_id: {
							type: "integer",
							"x-link-entity-type": "company",
							"x-link-lookup-field": "external_id",
						},
					},
				}}
				initialValues={{}}
				onValuesChange={vi.fn()}
			/>,
		);

		expect(view.container.querySelector('input[type="number"]')).toBeNull();
		expect(view.container.querySelector('[role="combobox"]')).toBeTruthy();
	});

	it("still renders the picker for a string foreign key", () => {
		const view = render(
			<DynamicSchemaForm
				schema={{
					type: "object",
					properties: {
						customer: { type: "string", "x-link-entity-type": "company" },
					},
				}}
				initialValues={{}}
				onValuesChange={vi.fn()}
			/>,
		);

		expect(view.container.querySelector('[role="combobox"]')).toBeTruthy();
	});
});

describe("date-only rendering", () => {
	/**
	 * `new Date("2026-08-01")` is parsed as UTC midnight, but the label is
	 * formatted in LOCAL time — so anywhere west of UTC the control displayed the
	 * previous calendar day. A date-only value has no timezone and must be read
	 * as a local calendar date.
	 */
	it("shows the same calendar day in a timezone west of UTC", () => {
		const originalOffset = Date.prototype.getTimezoneOffset;
		// America/Los_Angeles in August: UTC-7, i.e. +420 minutes.
		Date.prototype.getTimezoneOffset = () => 420;
		try {
			const view = render(
				<DynamicSchemaForm
					schema={{
						type: "object",
						properties: {
							issued_on: { type: "string", format: "date" },
						},
					}}
					initialValues={{ issued_on: "2026-08-01" }}
					onValuesChange={vi.fn()}
				/>,
			);
			expect(view.container.textContent).toContain("Aug 01, 2026");
			expect(view.container.textContent).not.toContain("Jul 31");
		} finally {
			Date.prototype.getTimezoneOffset = originalOffset;
		}
	});
});

