import { describe, expect, it } from "vitest";
import { buildMetadataPatch } from "./index";

/**
 * These two cases originally asserted a minimal patch — only the changed key,
 * only the cleared key. That contract could not survive contact with the
 * server, which validates the patch as a document rather than the merge of
 * patch and stored row: a payload of `{invoice_number}` alone fails validation
 * the moment the type declares `due_date` required. They now assert the whole
 * current object plus explicit nulls for cleared keys, and the "did anything
 * change" question is answered separately by returning `undefined`.
 */
describe("buildMetadataPatch", () => {
	it("sends the whole object when one field changes, so required keys survive", () => {
		expect(
			buildMetadataPatch(
				{ invoice_number: "INV-2", due_date: "2026-08-01", status: "draft" },
				{ invoice_number: "INV-1", due_date: "2026-08-01", status: "draft" },
			),
		).toEqual({
			invoice_number: "INV-2",
			due_date: "2026-08-01",
			status: "draft",
		});
	});

	it("transmits clears as explicit nulls alongside the retained keys", () => {
		expect(
			buildMetadataPatch(
				{ invoice_number: "INV-1", status: "draft" },
				{ invoice_number: "INV-1", due_date: "2026-08-01", status: "draft" },
			),
		).toEqual({
			invoice_number: "INV-1",
			due_date: null,
			status: "draft",
		});
	});

	it("returns undefined when nothing changed, so a name-only edit sends no metadata", () => {
		expect(
			buildMetadataPatch(
				{ invoice_number: "INV-1", status: "draft" },
				{ invoice_number: "INV-1", status: "draft" },
			),
		).toBeUndefined();
	});

	it("treats a newly added key as a change", () => {
		expect(
			buildMetadataPatch({ invoice_number: "INV-1", note: "hi" }, { invoice_number: "INV-1" }),
		).toEqual({ invoice_number: "INV-1", note: "hi" });
	});
});

