/**
 * The linked-entity picker must resolve an entity by its declared
 * `x-link-lookup-field`.
 *
 * The mock here emulates the REAL `manage_entity.list` search predicate —
 * `name ILIKE $1 OR metadata->>'domain' ILIKE $1` — rather than returning the
 * row unconditionally. That distinction is the whole point of the test: a mock
 * that answers every query with the row proves only that the client does not
 * drop it, while the server would never have sent it. Wiring the combobox query
 * to `search` emptied the picker the moment a user typed a lookup value such as
 * an `external_id`, because the server cannot match that field.
 */

import { fireEvent, render } from "@testing-library/react";
// @ts-expect-error jsdom is available in the workspace without bundled types here.
import { JSDOM } from "jsdom";
import { describe, expect, it, vi } from "vitest";

const CANDIDATES = [
	{
		id: "e1",
		name: "Acme GmbH",
		slug: "acme",
		entity_type: "company",
		metadata: { external_id: 4021 },
	},
];

vi.mock("@/lib/api", async (importOriginal) => {
	const actual = await importOriginal<Record<string, unknown>>();
	return {
		...actual,
		useEntitiesByType: (
			_type: string,
			_org: unknown,
			opts?: { search?: string },
		) => {
			const q = opts?.search?.toLowerCase();
			// Mirrors the server: name and the hardcoded `domain` key only. Notably
			// NOT metadata.external_id — that is the gap this guards.
			const entities = q
				? CANDIDATES.filter(
						(e) =>
							e.name.toLowerCase().includes(q) ||
							String(e.metadata.domain ?? "")
								.toLowerCase()
								.includes(q),
					)
				: CANDIDATES;
			return { data: { entities } };
		},
	};
});

const { DynamicSchemaForm } = await import("./dynamic-schema-form");

const dom = new JSDOM("<!doctype html><html><body></body></html>", {
	url: "http://localhost",
});

