proto.hasPointerCapture ??= () => false;
proto.setPointerCapture ??= () => {};
proto.releasePointerCapture ??= () => {};
proto.scrollIntoView ??= () => {};

function renderPicker() {
	const onValuesChange = vi.fn();
	const view = render(
		<DynamicSchemaForm
			schema={{
				type: "object",
				properties: {
					customer_id: {
						type: "integer",
						"x-link-entity-type": "company",
						"x-link-lookup-field": "external_id",
					},
				},
			}}
			initialValues={{}}
			onValuesChange={onValuesChange}
			orgContext={{ organizationId: "org_test", slug: "test-org" }}
		/>,
	);
	return { view, onValuesChange };
}

describe("linked-entity picker against the real search contract", () => {
	it("finds an entity by its declared lookup field", () => {
		const { view, onValuesChange } = renderPicker();
		fireEvent.click(view.container.querySelector("[role=combobox]") as Element);

		fireEvent.change(view.getByPlaceholderText("Search company..."), {
			target: { value: "4021" },
		});

		expect(view.getByRole("option", { name: /Acme GmbH/ })).toBeTruthy();
		fireEvent.click(view.getByRole("option", { name: /Acme GmbH/ }));
		expect(onValuesChange.mock.calls.at(-1)?.[0]).toEqual({
			customer_id: 4021,
		});
	});

	it("still narrows on a name query", () => {
		const { view } = renderPicker();
		fireEvent.click(view.container.querySelector("[role=combobox]") as Element);

		fireEvent.change(view.getByPlaceholderText("Search company..."), {
			target: { value: "zzz-no-such-company" },
		});

		expect(view.queryByRole("option", { name: /Acme GmbH/ })).toBeNull();
	});
});

