/**
 * The shared post-verification path for every routed Slack connection.
 *
 * Ordering is load-bearing and deliberately NOT "invalidate first". Nothing
 * upstream of here authenticates the request: `/api/v1/app-webhooks/slack` is
 * public and carries no org context, and Slack's `v0` signature is checked by
 * the Chat SDK adapter — which only runs once `forwardWebhook` hands the
 * request to it (see `chat-instance-manager.ts`, "Inbound webhook
 * authentication is performed by the platform's Chat SDK adapter"). Moving the
 * ACL invalidation ahead of that forward would let an unauthenticated POST
 * naming any `team_id` flip that workspace's ACL to `stale` and, because the
 * gate fails closed, deny recall until the next periodic sync.
 *
 * The cost of this ordering is that a delivery failure drops the revocation
 * signal for that event; the periodic sync remains the reconciler, so access
 * is stale-but-bounded rather than trivially deniable by anyone on the
 * internet. Closing that gap properly means verifying the signature here
 * before invalidating, which needs the connector's declared webhook schema
 * plumbed into this layer — a separate change.
 */
private async forwardRoutedWebhook(
  connection: Pick<PlatformConnection, "id" | "organizationId">,
  request: Request,
  body: string,
  teamJoinEvent: ParsedSlackTeamJoinEvent | null,
  memberLeftEvent: ParsedSlackMemberLeftEvent | null,
): Promise<Response> {
  if (!(await this.deps.ensureConnectionRunning(connection.id))) {
    return new Response("Slack connection unavailable", { status: 503 });
  }

  const response = await this.deps.forwardWebhook(
    connection.id,
    this.cloneRequestWithBody(request, body),
  );
  if (!response.ok) return response;

  if (memberLeftEvent) {
    if (!connection.organizationId) {
      throw new Error(
        `Slack membership removal for ${connection.id} has no organization scope`,
      );
    }
    const invalidated = await invalidateSlackConnectionAcl({
      organizationId: connection.organizationId,
      connectionId: connection.id,
    });
    logger.info(
      {
        organizationId: connection.organizationId,
        connectionId: connection.id,
        teamId: memberLeftEvent.teamId,
        channelId: memberLeftEvent.channelId,
        userId: memberLeftEvent.userId,
        invalidated,
      },
      "Slack channel membership revoked — invalidated ACL freshness",
    );
  }

  if (teamJoinEvent) {
    await this.handleTeamJoinWelcome(connection.id, teamJoinEvent);
  }
  return response;
}

