const appId = env.get("SLACK_APP_ID");
if (!token || !appId) throw new Error("missing SLACK_CONFIG_TOKEN / SLACK_APP_ID");

async function slack(method: string, body: Record<string, unknown>) {
  const resp = await fetch(`https://slack.com/api/${method}`, {
    method: "POST",
    headers: {
      authorization: `Bearer ${token}`,
      "content-type": "application/json; charset=utf-8",
    },
    body: JSON.stringify(body),
  });
  return (await resp.json()) as Record<string, unknown>;
}

// 1) Export live — the base we patch, so nothing else is disturbed.
const exported = await slack("apps.manifest.export", { app_id: appId });
if (!exported.ok) throw new Error(`export failed: ${exported.error}`);
