}

const updated = await slack("apps.manifest.update", { app_id: appId, manifest });
if (!updated.ok) throw new Error(`update failed: ${JSON.stringify(updated)}`);
console.log(`update: ok (permissions_updated=${updated.permissions_updated})`);

