 * Both writes commit in one transaction so the persisted reason cannot be lost
 * between the state flip and the column write.
 *
 * An unchanged reason is a no-op. ACL sync retries on a fixed tick, so a single
 * outage would otherwise rewrite `connections.updated_at` every tick — and that
 * column is the memo key `ChatInstanceManager` hydrates chat adapters against
 * (`rowVersion`), so a repeated identical failure would tear down and rehydrate
 * otherwise-working Slack instances for the length of the outage.
 */
export async function markConnectionAclFailed(
  organizationId: string,
  connectionId: string,
  reason: string,
): Promise<void> {
  const sql = getDb();
  await sql.begin(async (tx) => {
    await tx`
      UPDATE authz_source_acl_state
      SET freshness_state = 'failed', updated_at = current_timestamp
      WHERE organization_id = ${organizationId}
        AND connection_id = ${connectionId}
        AND freshness_state IS DISTINCT FROM 'failed'
    `;
    await tx`
      UPDATE connections
      SET error_message = ${formatAclErrorMessage(reason)}, updated_at = current_timestamp
      WHERE organization_id = ${organizationId}
        AND deleted_at IS NULL
        AND ${tx.unsafe(aclConnectionIdSql())} = ${connectionId}
        AND (
          error_message IS NULL
          OR left(error_message, ${ACL_ERROR_MESSAGE_PREFIX.length}) = ${ACL_ERROR_MESSAGE_PREFIX}
        )
        AND error_message IS DISTINCT FROM ${formatAclErrorMessage(reason)}
    `;
  });
}

