// state the chain can produce. Scoped hard to the TEK2027 series so nothing
// else is touched, and it reports what it saw before deleting.
export default async (_c, client) => {
  const found = await client.query(
    "SELECT id, metadata->>'document_no' AS no FROM entities WHERE entity_type='quote' AND deleted_at IS NULL AND metadata->>'document_no' LIKE 'TEK2027%' ORDER BY id",
  );
  const rows = found?.rows ?? found ?? [];
  const deleted = [];
  const errors = [];
  for (const r of rows) {
    try {
      await client.entities.delete({ entity_id: Number(r.id) });
      deleted.push(r.no);
    } catch (e) {
      if (errors.length < 3) errors.push(String(e?.message ?? e).slice(0, 140));
    }
  }
  return { seen: rows.length, deleted: deleted.length, errors };
};

