// Prove the chain is TRAVERSABLE, not merely that rows exist: walk
// payment -> invoice -> order -> quote -> customer purely through
// entity_relationships and count how many complete the full walk.
export default async (_c, client) => {
  const counts = await client.query(
    "SELECT entity_type, count(*) AS n FROM entities WHERE deleted_at IS NULL GROUP BY 1 ORDER BY 1",
  );
  const edges = await client.query(
    "SELECT rt.slug, count(*) AS n FROM entity_relationships r JOIN entity_relationship_types rt ON rt.id = r.relationship_type_id GROUP BY 1 ORDER BY 2 DESC",
  );
  const walk = await client.query(`
    SELECT count(*) AS full_chains
    FROM entities p
    JOIN entity_relationships pi ON pi.from_entity_id = p.id
      AND pi.relationship_type_id = (SELECT id FROM entity_relationship_types WHERE slug='payment_invoice')
    JOIN entity_relationships io ON io.from_entity_id = pi.to_entity_id
      AND io.relationship_type_id = (SELECT id FROM entity_relationship_types WHERE slug='invoice_from_order')
    JOIN entity_relationships oq ON oq.from_entity_id = io.to_entity_id
      AND oq.relationship_type_id = (SELECT id FROM entity_relationship_types WHERE slug='order_from_quote')
    JOIN entity_relationships qc ON qc.from_entity_id = oq.to_entity_id
      AND qc.relationship_type_id = (SELECT id FROM entity_relationship_types WHERE slug='quote_customer')
    WHERE p.entity_type='payment' AND p.deleted_at IS NULL
  `);
  return {
    entities: counts?.rows ?? counts,
    edges: edges?.rows ?? edges,
    payment_to_customer_full_walk: walk?.rows ?? walk,
  };
};

