// listTypes returns the org's OWN types PLUS public schemas, so filter on
// organization_id or the count is inflated.
const ORG = "REDACTED";
export default async (_c, client) => {
  const all = await client.entitySchema.listTypes();
  const list = all?.types ?? all?.entity_types ?? all ?? [];
  const own = list.filter((t) => t.organization_id === ORG);
  const rt = await client.query(
    `SELECT count(*) AS n FROM entity_relationship_types WHERE organization_id='${ORG}'`,
  );
  return {
    own_entity_types: own.length,
    own_slugs: own.map((t) => t.slug ?? t.key).sort(),
    visible_including_public: list.length,
    relationship_types: rt?.rows ?? rt,
  };
};

