// Master data and inventory for the modules that had no entity type until now:
// SabitKiymet (fixed-asset), MasrafYeri (cost-center), Mahsup (offset) — plus
// stock movements, so `product.on_hand` has a movement history behind it rather
// than being a number nobody can explain.
//
// Deterministic (seeded LCG) and idempotent by name, matching seed-full.ts.
// The sandbox caps a script at 200 SDK calls; this budgets and reports
// `remaining` so it can be re-run until 0.
const BUDGET = 180;

export default async (_ctx, client) => {
  let s = 44017;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const money = (n) => Math.round(n * 100) / 100;
  const day = (o) => new Date(Date.UTC(2028, 0, 4) + o * 86400000).toISOString().slice(0, 10);

  let calls = 0;
  const out = { fixed_assets: 0, cost_centers: 0, offsets: 0, movements: 0, errors: [], remaining: 0 };
  const note = (e) => {
    if (out.errors.length < 4) out.errors.push(String(e?.message ?? e).slice(0, 150));
  };

  // Existing names per type, so a re-run skips instead of colliding — a
  // soft-deleted row still holds its name, so a collision is unrecoverable here.
  const taken = new Set();
  for (const t of ["fixed-asset", "cost-center", "offset", "stock-movement"]) {
    const r = await client.entities.list({ entity_type: t, limit: 500 });
    calls++;
    for (const e of r.entities ?? []) taken.add(`${t}:${e.name}`);
  }

  const customers = (await client.entities.list({ entity_type: "customer", limit: 500 })).entities ?? [];
  const products = (await client.entities.list({ entity_type: "product", limit: 500 })).entities ?? [];
  const warehouses = (await client.entities.list({ entity_type: "warehouse", limit: 100 })).entities ?? [];
  calls += 3;
  if (products.length === 0) return { error: "seed masters first" };

  const make = async (type, name, metadata, counter) => {
    if (taken.has(`${type}:${name}`)) return null;
    if (calls + 2 > BUDGET) {
      out.remaining++;
      return null;
    }
    try {
      const r = await client.entities.create({ type, name, metadata });
      calls++;
      out[counter]++;
      return Number(r.entity.id);
    } catch (e) {
      note(e);
      return null;
    }
  };

  // --- Masraf Yeri -------------------------------------------------------
  const centers = [
    ["Uretim", "MY-100"], ["Montaj", "MY-110"], ["Kalite Kontrol", "MY-120"],
    ["Bakim Onarim", "MY-130"], ["Depo", "MY-200"], ["Sevkiyat", "MY-210"],
    ["Satis", "MY-300"], ["Muhasebe", "MY-400"], ["Idari Isler", "MY-410"],
  ];
  for (const [title, code] of centers) {
    await make("cost-center", title, { title, code, is_active: true }, "cost_centers");
  }

  // --- Sabit Kiymet ------------------------------------------------------
  const assets = [
    ["CNC Torna Tezgahi", "SK-1001", 1850000, 10], ["Dik Isleme Merkezi", "SK-1002", 2400000, 10],
    ["Hidrolik Pres 160T", "SK-1003", 780000, 12], ["Kaynak Robotu", "SK-1004", 1250000, 8],
    ["Forklift 3T", "SK-2001", 420000, 7], ["Kompresor 500L", "SK-2002", 165000, 10],
    ["Jenerator 250kVA", "SK-2003", 590000, 12], ["Vinc 5T", "SK-2004", 310000, 15],
    ["Olcum Cihazi CMM", "SK-3001", 940000, 8], ["Sunucu Dolabi", "SK-4001", 220000, 5],
    ["Ofis Mobilyasi", "SK-4002", 85000, 8], ["Binek Arac", "SK-4003", 1450000, 5],
  ];
  for (const [title, code, cost, life] of assets) {
    const age = int(1, 5);
    await make(
      "fixed-asset",
      title,
      {
        title,
        code,
        acquisition_date: day(-age * 365 + int(0, 300)),
        acquisition_cost: money(cost),
        depreciation_method: rnd() < 0.75 ? "normal" : "azalan_bakiye",
        useful_life_years: life,
        accumulated_depreciation: money(Math.min(cost, (cost / life) * age)),
        status: rnd() < 0.9 ? "active" : "disposed",
      },
      "fixed_assets",
    );
  }

  // --- Stok Hareketleri --------------------------------------------------
  // Giris raises stock, cikis lowers it. Bound to a warehouse when one exists,
  // because a movement without a location is not an inventory record.
  const wh = warehouses[0] ? Number(warehouses[0].id) : null;
  for (let i = 0; i < 60; i++) {
    const p = products[int(0, products.length - 1)];
    const dir = rnd() < 0.45 ? "giris" : "cikis";
    const no = `STK2028${String(i + 1).padStart(6, "0")}`;
    const id = await make(
      "stock-movement",
      `${no} - ${p.metadata.title}`,
      {
        document_no: no,
        product_id: p.id,
        warehouse_id: wh,
        date: day(int(0, 330)),
        direction: dir,
        quantity: p.metadata.unit === "ADET" ? int(1, 40) : int(10, 500),
        unit_cost: money((p.metadata.list_price ?? 100) * (0.6 + rnd() * 0.25)),
      },
      "movements",
    );
    if (id && calls + 2 <= BUDGET) {
      try {
        await client.entities.link({
          from_entity_id: id,
          to_entity_id: p.id,
          relationship_type_slug: "movement_product",
          source: "api",
        });
        calls++;
      } catch (e) {
        note(e);
      }
    }
  }

  // --- Mahsup ------------------------------------------------------------
  for (let i = 0; i < 8 && customers.length > 0; i++) {
    const c = customers[int(0, customers.length - 1)];
    const no = `MHS2028${String(i + 1).padStart(6, "0")}`;
    await make(
      "offset",
      `${no} - ${c.metadata.title}`,
      {
        document_no: no,
        date: day(int(30, 330)),
        amount: money(int(5000, 180000) + rnd()),
        currency: c.metadata.currency ?? "TRY",
        customer_id: c.id,
        status: rnd() < 0.7 ? "posted" : "draft",
        description: "Cari hesap mahsuplasmasi",
      },
      "offsets",
    );
  }

  out.calls_used = calls;
  return out;
};

