  const mv = await client.query(
    "SELECT count(*) AS n FROM entity_relationships r JOIN entity_relationship_types rt ON rt.id=r.relationship_type_id WHERE rt.slug='movement_product'",
  );
  return { entities: ents?.rows ?? ents, total_edges: edges?.rows ?? edges, movement_product_edges: mv?.rows ?? mv };
};

