// SPIKE: can a direct SDK write mutate a POSTED invoice — i.e. bypass any rule a
// Behavior would enforce? This is the decisive test for "Behaviors enforce the
// rules": that claim is only true if no other path can write.
//
// Non-destructive by construction: it changes grand_total, reads it back, then
// restores the original value and verifies the restore.
export default async (_c, client) => {
  const posted = await client.query(
    "SELECT id, metadata->>'document_no' AS no, metadata->>'status' AS status, (metadata->>'grand_total')::numeric AS gt, metadata->>'customer_id' AS cust, metadata->>'date' AS date, metadata->>'document_type' AS dt FROM entities WHERE entity_type='invoice' AND deleted_at IS NULL AND metadata->>'status'='posted' ORDER BY id LIMIT 1",
  );
  const rows = posted?.rows ?? posted ?? [];
  if (rows.length === 0) return { skipped: "no posted invoice found" };
  const inv = rows[0];
  const original = Number(inv.gt);
  const tampered = Math.round((original + 99999) * 100) / 100;

  const required = { customer_id: Number(inv.cust), date: inv.date, document_type: inv.dt, status: "posted" };

  const result = { document_no: inv.no, status_before: inv.status, original_total: original };

  // 1. attempt the illegal mutation
  try {
    await client.entities.update({
      entity_id: Number(inv.id),
      metadata: { ...required, grand_total: tampered },
    });
    result.write_accepted = true;
  } catch (e) {
    result.write_accepted = false;
    result.refusal = String(e?.message ?? e).slice(0, 200);
  }

  // 2. read back what actually landed
  const after = await client.query(
    `SELECT (metadata->>'grand_total')::numeric AS gt FROM entities WHERE id=${Number(inv.id)}`,
  );
  const nowVal = Number((after?.rows ?? after)[0].gt);
  result.total_after_attempt = nowVal;
  result.posted_document_was_mutated = nowVal !== original;

  // 3. restore if it changed, and prove the restore landed
  if (nowVal !== original) {
    await client.entities.update({
      entity_id: Number(inv.id),
      metadata: { ...required, grand_total: original },
    });
    const back = await client.query(
      `SELECT (metadata->>'grand_total')::numeric AS gt FROM entities WHERE id=${Number(inv.id)}`,
    );
    result.restored_to = Number((back?.rows ?? back)[0].gt);
    result.restore_ok = Number((back?.rows ?? back)[0].gt) === original;
  }
  return result;
};

