// SPIKE 3: is a Behavior-performed check-then-write ATOMIC, or advisory?
//
// The claim under test is "a Behavior that performs the mutation can enforce the
// rule". That is only true if the guard it evaluates and the write it then makes
// are in ONE transaction. If they are two, another writer can change the state
// in between and the guard approves a write that is illegal by the time it lands.
//
// This simulates that interleaving deterministically inside one script:
//   1. read status               (guard says: draft, safe to edit)
//   2. a concurrent writer posts it
//   3. perform the write the guard approved
// If step 3 lands, the guard was advisory. Everything is restored at the end.
export default async (_c, client) => {
  const rows = await client.query(
    "SELECT id, metadata->>'document_no' AS no, metadata->>'status' AS status, (metadata->>'grand_total')::numeric AS gt, metadata->>'customer_id' AS cust, metadata->>'date' AS date, metadata->>'document_type' AS dt FROM entities WHERE entity_type='invoice' AND deleted_at IS NULL AND metadata->>'status'='draft' ORDER BY id LIMIT 1",
  );
  const list = rows?.rows ?? rows ?? [];
  if (list.length === 0) return { skipped: "no draft invoice available" };
  const inv = list[0];
  const req = { customer_id: Number(inv.cust), date: inv.date, document_type: inv.dt };
  const original = Number(inv.gt);
  const r = { document_no: inv.no, guard_read_status: inv.status };

  // 1. THE GUARD — exactly what a Behavior would evaluate before writing.
  const mayEdit = inv.status === "draft";
  r.guard_decision = mayEdit ? "allow" : "deny";
  if (!mayEdit) return { ...r, note: "guard denied; nothing to prove" };

  // 2. A CONCURRENT WRITER posts the document, after the guard read it.
  await client.entities.update({
    entity_id: Number(inv.id),
    metadata: { ...req, status: "posted" },
  });
  const mid = await client.query(
    `SELECT metadata->>'status' AS s FROM entities WHERE id=${Number(inv.id)}`,
  );
  r.status_when_write_lands = (mid?.rows ?? mid)[0].s;

  // 3. THE APPROVED WRITE proceeds on the guard's stale decision.
  const tampered = Math.round((original + 12345) * 100) / 100;
  try {
    await client.entities.update({
      entity_id: Number(inv.id),
      metadata: { ...req, status: "posted", grand_total: tampered },
    });
    r.approved_write_landed = true;
  } catch (e) {
    r.approved_write_landed = false;
    r.refusal = String(e?.message ?? e).slice(0, 180);
  }
  const after = await client.query(
    `SELECT (metadata->>'grand_total')::numeric AS gt FROM entities WHERE id=${Number(inv.id)}`,
  );
  r.total_after = Number((after?.rows ?? after)[0].gt);
  r.guard_was_advisory = r.total_after !== original && r.status_when_write_lands === "posted";

  // restore: total, then status back to draft
  await client.entities.update({
    entity_id: Number(inv.id),
    metadata: { ...req, status: "posted", grand_total: original },
  });
  await client.entities.update({
    entity_id: Number(inv.id),
    metadata: { ...req, status: "draft" },
  });
  const back = await client.query(
    `SELECT metadata->>'status' AS s, (metadata->>'grand_total')::numeric AS gt FROM entities WHERE id=${Number(inv.id)}`,
  );
  const b = (back?.rows ?? back)[0];
  r.restored = { status: b.s, grand_total: Number(b.gt) };
  r.restore_ok = b.s === "draft" && Number(b.gt) === original;
  return r;
};

