// Masters for the URETIM pass: work centres, resources (machine / mould /
// labour), operations, routings and shifts — plus the cost-element chart.
//
// Prodma is a plastics/injection shop (KALIP moulds, GOZ_ADET cavity counts,
// URETIM_ENJEKSIYON_KALITE), so the masters here are that shop, not generic
// manufacturing filler.
//
// Deterministic and idempotent by name, matching the other seeds. The sandbox
// caps a script at 200 SDK calls; this budgets and reports `remaining` so it
// can be re-run until 0.
const BUDGET = 180;

export default async (_ctx, client) => {
  let s = 90211;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const dec = (lo, hi) => Math.round((lo + rnd() * (hi - lo)) * 100) / 100;

  let calls = 0;
  const out = {
    work_centers: 0, resources: 0, operations: 0, routings: 0, shifts: 0,
    cost_elements: 0, edges: 0, errors: [], remaining: 0,
  };
  const note = (e) => {
    if (out.errors.length < 5) out.errors.push(String(e?.message ?? e).slice(0, 160));
  };

  const byName = {};
  const taken = new Set();
  for (const t of ["work-center", "resource", "operation", "routing", "shift", "cost-element", "cost-center", "product", "ledger-account"]) {
    const r = await client.entities.list({ entity_type: t, limit: 500 });
    calls++;
    byName[t] = new Map();
    for (const e of r.entities ?? []) {
      taken.add(`${t}:${e.name}`);
      byName[t].set(e.name, Number(e.id));
    }
  }
  const products = [...byName["product"].entries()];
  const centers = byName["cost-center"];
  const accounts = [...byName["ledger-account"].entries()];
  if (products.length === 0) return { error: "seed masters first" };

  const make = async (type, name, metadata, counter) => {
    const known = byName[type]?.get(name);
    if (known) return known;
    if (taken.has(`${type}:${name}`)) return null;
    if (calls + 2 > BUDGET) { out.remaining++; return null; }
    try {
      const r = await client.entities.create({ type, name, metadata });
      calls++;
      out[counter]++;
      const id = Number(r.entity.id);
      byName[type]?.set(name, id);
      return id;
    } catch (e) { note(e); return null; }
  };

  const link = async (src, tgt, slug) => {
    if (!src || !tgt) return;
    if (calls + 1 > BUDGET) { out.remaining++; return; }
    try {
      await client.entities.link({ source_entity_id: src, target_entity_id: tgt, relationship_type_slug: slug });
      calls++;
      out.edges++;
    } catch (e) { note(e); }
  };

  // --- Uretim Yeri -------------------------------------------------------
  const wcDefs = [
    ["Enjeksiyon Salonu", "UY-10", "Enjeksiyon", "Uretim"],
    ["Kalip Atolyesi", "UY-20", "Kalip", "Bakim Onarim"],
    ["Montaj Hatti", "UY-30", "Montaj", "Montaj"],
    ["Boyahane", "UY-40", "Yuzey Islem", "Uretim"],
    ["Kalite Laboratuvari", "UY-50", "Kalite", "Kalite Kontrol"],
    ["Paketleme", "UY-60", "Paketleme", "Sevkiyat"],
  ];
  const workCenters = {};
  for (const [title, code, line, cc] of wcDefs) {
    const ccId = centers.get(cc) ?? null;
    const id = await make("work-center", title, { title, code, work_line: line, cost_center_id: ccId }, "work_centers");
    if (id) {
      workCenters[title] = id;
      await link(id, ccId, "work_center_cost_center");
    }
  }

  // --- Uretim Araci ------------------------------------------------------
  // catalog_class is the CLASS a routing line references; several units share
  // one class, which is what makes an alternative machine possible.
  const resDefs = [
    ["Enjeksiyon Presi 150T #1", "MK-1501", "machine", "PRES-150", "Enjeksiyon Salonu", 150],
    ["Enjeksiyon Presi 150T #2", "MK-1502", "machine", "PRES-150", "Enjeksiyon Salonu", 150],
    ["Enjeksiyon Presi 250T", "MK-2501", "machine", "PRES-250", "Enjeksiyon Salonu", 250],
    ["Enjeksiyon Presi 400T", "MK-4001", "machine", "PRES-400", "Enjeksiyon Salonu", 400],
    ["Kurutma Firini", "MK-5001", "machine", "FIRIN", "Enjeksiyon Salonu", 0],
    ["Granul Karistirici", "MK-5002", "machine", "KARIS", "Enjeksiyon Salonu", 0],
    ["Ultrasonik Kaynak", "MK-6001", "machine", "ULTRA", "Montaj Hatti", 0],
    ["Montaj Tezgahi", "MK-6002", "machine", "MONTAJ", "Montaj Hatti", 0],
    ["Boya Kabini", "MK-7001", "machine", "BOYA", "Boyahane", 0],
    ["CMM Olcum Cihazi", "MK-8001", "machine", "CMM", "Kalite Laboratuvari", 0],
    ["Kalip 4 Gozlu Kapak", "KL-1001", "mold", "KALIP-4G", "Kalip Atolyesi", 0],
    ["Kalip 8 Gozlu Tapa", "KL-1002", "mold", "KALIP-8G", "Kalip Atolyesi", 0],
    ["Kalip 2 Gozlu Govde", "KL-1003", "mold", "KALIP-2G", "Kalip Atolyesi", 0],
    ["Kalip 16 Gozlu Klips", "KL-1004", "mold", "KALIP-16G", "Kalip Atolyesi", 0],
    ["Pres Operatoru", "IS-100", "labor", "OPR-PRES", "Enjeksiyon Salonu", 0],
    ["Montaj Iscisi", "IS-200", "labor", "OPR-MONTAJ", "Montaj Hatti", 0],
    ["Kalite Kontrolcu", "IS-300", "labor", "OPR-KALITE", "Kalite Laboratuvari", 0],
    ["Kalipci", "IS-400", "labor", "OPR-KALIP", "Kalip Atolyesi", 0],
  ];
  const resources = {};
  for (const [title, code, type, cls, wc, power] of resDefs) {
    const wcId = workCenters[wc] ?? byName["work-center"].get(wc) ?? null;
    const ccId = centers.get(wcDefs.find((w) => w[0] === wc)?.[3]) ?? null;
    const cavity = type === "mold" ? Number(cls.replace(/\D/g, "")) || null : null;
    const id = await make("resource", title, {
      title, code, resource_type: type, catalog_class: cls,
      count: type === "labor" ? int(2, 8) : 1,
      capacity_percent: type === "machine" ? dec(78, 96) : null,
      installed_power: power || null,
      cavity_count: cavity,
      work_center_id: wcId,
      cost_center_id: ccId,
      // Moulds are serviced by shot count, not by date — BAKIM_BASKI_SAYISI.
      maintenance_cycle_count: type === "mold" ? int(120000, 900000) : null,
      maintenance_warn_at: type === "mold" ? int(100000, 110000) : null,
    }, "resources");
    if (id) {
      resources[title] = id;
      await link(id, ccId, "resource_cost_center");
    }
  }

  // --- Vardiya -----------------------------------------------------------
  for (const [title, code, a, b, h] of [
    ["Vardiya 1", "V1", "08:00", "16:00", 8],
    ["Vardiya 2", "V2", "16:00", "24:00", 8],
    ["Vardiya 3", "V3", "00:00", "08:00", 8],
  ]) {
    await make("shift", title, { title, code, start_time: a, end_time: b, hours: h }, "shifts");
  }

  // --- Maliyet Kalemi ----------------------------------------------------
  const ceDefs = [
    ["Direkt Hammadde", "MK-710", "direct_material"],
    ["Direkt Iscilik", "MK-720", "direct_labor"],
    ["Makina Amortisman", "MK-730", "machine"],
    ["Enerji", "MK-740", "energy"],
    ["Genel Uretim Gideri", "MK-750", "overhead"],
    ["Kalip Amortisman", "MK-760", "machine"],
  ];
  for (let i = 0; i < ceDefs.length; i++) {
    const [title, code, type] = ceDefs[i];
    const acct = accounts.length ? accounts[i % accounts.length][1] : null;
    const id = await make("cost-element", title, { title, code, element_type: type, ledger_account_id: acct }, "cost_elements");
    await link(id, acct, "cost_element_account");
  }

  // --- Operasyon ---------------------------------------------------------
  // Machine and labour times are held apart on purpose: a press runs unattended
  // after setup, so labour run time is a fraction of machine run time and the
  // two consume different rates in costing.
  const opDefs = [
    ["Granul Kurutma", "OP-010", "sequential", "FIRIN", 30, 240, 10, 15],
    ["Granul Karistirma", "OP-020", "sequential", "KARIS", 15, 45, 15, 20],
    ["Enjeksiyon 150T", "OP-100", "sequential", "PRES-150", 45, 0.42, 45, 0.05],
    ["Enjeksiyon 250T", "OP-110", "sequential", "PRES-250", 60, 0.68, 60, 0.06],
    ["Enjeksiyon 400T", "OP-120", "sequential", "PRES-400", 90, 1.15, 90, 0.08],
    ["Capak Alma", "OP-200", "sequential", "MONTAJ", 5, 0.35, 5, 0.35],
    ["Ultrasonik Kaynak", "OP-210", "sequential", "ULTRA", 20, 0.22, 20, 0.22],
    ["Montaj", "OP-220", "sequential", "MONTAJ", 10, 0.8, 10, 0.8],
    ["Boyama", "OP-300", "sequential", "BOYA", 40, 0.6, 40, 0.25],
    ["Kalite Kontrol", "OP-400", "alternative", "CMM", 0, 0.15, 0, 0.15],
    ["Paketleme", "OP-500", "sequential", "MONTAJ", 5, 0.18, 5, 0.18],
    ["Kalip Degisim", "OP-900", "parallel", "PRES-250", 120, 0, 120, 0],
  ];
  const operations = {};
  for (const [title, code, flow, cls, msu, mrun, lsu, lrun] of opDefs) {
    const id = await make("operation", title, {
      title, code, flow_type: flow, machine_class: cls, machine_count: 1,
      machine_setup_minutes: msu, machine_run_minutes: mrun,
      labor_class: cls.startsWith("PRES") ? "OPR-PRES" : "OPR-MONTAJ", labor_count: 1,
      labor_setup_minutes: lsu, labor_run_minutes: lrun,
    }, "operations");
    if (id) {
      operations[title] = id;
      const machine = resDefs.find((r) => r[3] === cls);
      await link(id, machine ? resources[machine[0]] ?? byName["resource"].get(machine[0]) : null, "operation_resource");
    }
  }

  // --- Rota --------------------------------------------------------------
  // Steps live inline: a route is read, versioned and released as one unit.
  const routeShapes = [
    ["Granul Kurutma", "Enjeksiyon 150T", "Capak Alma", "Kalite Kontrol", "Paketleme"],
    ["Granul Karistirma", "Enjeksiyon 250T", "Capak Alma", "Montaj", "Paketleme"],
    ["Granul Kurutma", "Enjeksiyon 400T", "Capak Alma", "Boyama", "Kalite Kontrol", "Paketleme"],
    ["Enjeksiyon 150T", "Ultrasonik Kaynak", "Montaj", "Paketleme"],
  ];
  const opIndex = new Map(opDefs.map((o) => [o[0], o]));
  for (let i = 0; i < Math.min(10, products.length); i++) {
    const [pName, pId] = products[i];
    const shape = routeShapes[i % routeShapes.length];
    const title = `Rota ${pName}`.slice(0, 90);
    const steps = shape.map((opName, k) => {
      const o = opIndex.get(opName);
      const oid = operations[opName] ?? byName["operation"].get(opName) ?? null;
      return {
        sequence: (k + 1) * 10,
        operation_id: oid,
        operation_code: o[1],
        machine_class: o[3],
        machine_setup_minutes: o[4],
        machine_run_minutes: o[5],
        labor_setup_minutes: o[6],
        labor_run_minutes: o[7],
      };
    });
    const id = await make("routing", title, {
      title, code: `RT-${String(1000 + i)}`, version: "1.0",
      product_id: pId, status: "released", steps,
    }, "routings");
    if (id) {
      await link(id, pId, "routing_product");
      for (const st of steps.slice(0, 3)) await link(id, st.operation_id, "routing_operation");
    }
  }

  out.calls = calls;
  return out;
};

