// Is the entity name-uniqueness constraint per entity-type, or org-wide?
// An ERP has a cost centre "Montaj", a work centre "Montaj Hatti" and an
// operation "Montaj" at the same time, so this is load-bearing.
export default async (_c, client) => {
  const out = {};

  // 1. Who currently holds the four names the operation seed failed on?
  const rows = await client.query(
    "SELECT entity_type, name, deleted_at IS NOT NULL AS deleted FROM entities WHERE name = ANY(ARRAY['Montaj','Kalite Kontrol','Paketleme','Ultrasonik Kaynak','ZZ_PROBE_NAME_SCOPE']) ORDER BY name, entity_type",
  );
  out.holders = (rows?.rows ?? rows).map((r) => `${r.entity_type} / ${r.name}${r.deleted ? " (deleted)" : ""}`);

  // 2. Two fresh names, one type each, then the SAME name under a second type.
  const probe = `ZZP_${(rows?.rows ?? rows).length}_${out.holders.length}`;
  const attempt = async (type, name) => {
    try {
      const r = await client.entities.create({ type, name, metadata: { title: name } });
      return { verdict: "ALLOWED", id: Number(r.entity.id) };
    } catch (e) {
      return { verdict: "DENIED", why: String(e?.message ?? e).slice(0, 140) };
    }
  };
  const first = await attempt("shift", probe);
  out.first_shift = first;
  const second = await attempt("operation", probe);
  out.second_operation_same_name = second;
  for (const r of [first, second]) {
    if (r.id) await client.entities.delete({ entity_id: r.id });
  }
  return out;
};

