// The routings were created before the operations existed, so every inline step
// stored `operation_id: null`. Re-resolve by operation_code and write the steps
// back. `entities.update` validates the PATCH rather than the merged result, so
// every required field has to travel with it.
export default async (_ctx, client) => {
  const out = { routings: 0, steps_fixed: 0, still_null: 0, errors: [] };
  const ops = (await client.entities.list({ entity_type: "operation", limit: 200 })).entities ?? [];
  const byCode = new Map();
  for (const o of ops) byCode.set(o.metadata?.code, Number(o.id));

  const routings = (await client.entities.list({ entity_type: "routing", limit: 200 })).entities ?? [];
  for (const r of routings) {
    const m = r.metadata ?? {};
    const steps = (m.steps ?? []).map((st) => {
      const id = st.operation_id ?? byCode.get(st.operation_code) ?? null;
      if (!st.operation_id && id) out.steps_fixed++;
      if (!id) out.still_null++;
      return { ...st, operation_id: id };
    });
    try {
      await client.entities.update({
        entity_id: Number(r.id),
        metadata: { title: m.title, product_id: m.product_id, code: m.code, version: m.version, status: m.status, steps },
      });
      out.routings++;
    } catch (e) {
      if (out.errors.length < 3) out.errors.push(String(e?.message ?? e).slice(0, 150));
    }
  }
  return out;
};

