// Repairs two things the first production seed left behind.
//
// 1. DUPLICATE OPERATIONS. Entity name uniqueness is ORG-WIDE, not scoped to
//    entity type, so "Montaj", "Kalite Kontrol", "Paketleme" and "Ultrasonik
//    Kaynak" were already taken by a cost centre / work centre / resource and
//    4 of 12 operations silently failed. The retry used an "OP " prefix and
//    created all 12, leaving 8 unprefixed duplicates to remove.
//
// 2. `operation_id: 0`. Writing `null` into an `integer` property does not
//    store null — it is coerced to 0. So a "no link yet" marker comes back as
//    a valid-looking entity id, and `??` never fires on it. Treat 0 as absent.
export default async (_ctx, client) => {
  const out = { duplicates_deleted: 0, routings: 0, steps_fixed: 0, still_null: 0, errors: [] };
  const note = (e) => {
    if (out.errors.length < 4) out.errors.push(String(e?.message ?? e).slice(0, 150));
  };
  const rows = async (sql) => {
    const r = await client.query(sql);
    return r?.rows ?? r ?? [];
  };

  const opRows = await rows(
    "SELECT id, name, metadata->>'code' AS code FROM entities WHERE entity_type='operation' AND deleted_at IS NULL ORDER BY id",
  );
  const keep = new Map();
  const drop = [];
  for (const o of opRows) {
    if (String(o.name).startsWith("OP ")) keep.set(o.code, Number(o.id));
    else drop.push(Number(o.id));
  }
  out.operations_kept = keep.size;
  for (const id of drop) {
    try {
      await client.entities.delete({ entity_id: id });
      out.duplicates_deleted++;
    } catch (e) {
      note(e);
    }
  }

  const rtRows = await rows(
    "SELECT id, metadata FROM entities WHERE entity_type='routing' AND deleted_at IS NULL ORDER BY id",
  );
  for (const r of rtRows) {
    const m = typeof r.metadata === "string" ? JSON.parse(r.metadata) : (r.metadata ?? {});
    const steps = (m.steps ?? []).map((st) => {
      const present = st.operation_id && Number(st.operation_id) > 0 ? Number(st.operation_id) : null;
      // Re-point even a present id: the 8 duplicates just went away.
      const id = keep.get(st.operation_code) ?? present;
      if (id && id !== present) out.steps_fixed++;
      if (!id) out.still_null++;
      return { ...st, operation_id: id };
    });
    try {
      await client.entities.update({
        entity_id: Number(r.id),
        // `entities.update` validates the PATCH, not the merged result, so every
        // required field has to travel with it.
        metadata: {
          title: m.title,
          product_id: m.product_id,
          code: m.code,
          version: m.version,
          status: m.status,
          steps,
        },
      });
      out.routings++;
    } catch (e) {
      note(e);
    }
  }
  return out;
};

// Transactions for the traceability and actual-costing clusters: lots (PARTI),
// cost-centre allocation rules (KESIN_MALIYET_DAGITIM_TABLOSU) and monthly
// actual cost rows (KESIN_MALIYET_SURE). Also links work orders to the routing
// they were released against.
//
// Deterministic and idempotent by name; re-run until `remaining` is 0.
const BUDGET = 180;

export default async (_ctx, client) => {
  let s = 771103;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const money = (n) => Math.round(n * 100) / 100;
  const day = (o) => new Date(Date.UTC(2028, 0, 4) + o * 86400000).toISOString().slice(0, 10);

  let calls = 0;
  const out = { lots: 0, allocations: 0, actual_costs: 0, wo_routing: 0, edges: 0, errors: [], remaining: 0 };
  const note = (e) => {
    if (out.errors.length < 5) out.errors.push(String(e?.message ?? e).slice(0, 160));
  };
  const rows = async (sql) => {
    calls++;
    const r = await client.query(sql);
    return r?.rows ?? r ?? [];
  };

  const taken = new Set();
  for (const t of ["lot", "cost-allocation", "actual-cost"]) {
    for (const e of await rows(
      `SELECT name FROM entities WHERE entity_type='${t}' AND deleted_at IS NULL`,
    )) taken.add(`${t}:${e.name}`);
  }
  const products = await rows(
    "SELECT id, name FROM entities WHERE entity_type='product' AND deleted_at IS NULL ORDER BY id LIMIT 40",
  );
  const centers = await rows(
    "SELECT id, name FROM entities WHERE entity_type='cost-center' AND deleted_at IS NULL ORDER BY id",
  );
  const workOrders = await rows(
    "SELECT id, name, metadata->>'product_id' AS product_id FROM entities WHERE entity_type='work-order' AND deleted_at IS NULL ORDER BY id",
  );
  const warehouses = await rows(
    "SELECT id, name FROM entities WHERE entity_type='warehouse' AND deleted_at IS NULL ORDER BY id",
  );
  const routings = await rows(
    "SELECT id, metadata->>'product_id' AS product_id FROM entities WHERE entity_type='routing' AND deleted_at IS NULL ORDER BY id",
  );
  if (products.length === 0 || centers.length === 0) return { error: "seed masters first" };
  const routingByProduct = new Map(routings.map((r) => [String(r.product_id), Number(r.id)]));

  const make = async (type, name, metadata, counter) => {
    if (taken.has(`${type}:${name}`)) return null;
    if (calls + 2 > BUDGET) { out.remaining++; return null; }
    try {
      const r = await client.entities.create({ type, name, metadata });
      calls++;
      out[counter]++;
      taken.add(`${type}:${name}`);
      return Number(r.entity.id);
    } catch (e) { note(e); return null; }
  };
  const link = async (from, to, slug) => {
    if (!from || !to) return;
    if (calls + 1 > BUDGET) { out.remaining++; return; }
    try {
      await client.entities.link({ from_entity_id: from, to_entity_id: to, relationship_type_slug: slug });
      calls++;
      out.edges++;
    } catch (e) { note(e); }
  };

  // --- work order -> routing --------------------------------------------
  // The route a run was RELEASED against, not the current one. That
  // distinction is what lets a cost variance be explained six months later.
  for (const wo of workOrders.slice(0, 12)) {
    const rt = routingByProduct.get(String(wo.product_id));
    if (rt) {
      await link(Number(wo.id), rt, "work_order_routing");
      out.wo_routing++;
    }
  }

  // --- Parti -------------------------------------------------------------
  // Prodma's lot key is two-part (PARTI_NO_1 string + PARTI_NO_2 int), so a
  // recall query matches on both, never on a concatenated display string.
  const statuses = ["released", "released", "released", "consumed", "quarantined", "open"];
  for (let i = 0; i < 20; i++) {
    const wo = workOrders.length ? workOrders[i % workOrders.length] : null;
    const p = wo?.product_id
      ? products.find((x) => String(x.id) === String(wo.product_id)) ?? products[i % products.length]
      : products[i % products.length];
    const no1 = `P28${String(100 + i)}`;
    const no2 = int(1, 9);
    const title = `Parti ${no1}-${no2}`;
    const wh = warehouses.length ? warehouses[i % warehouses.length] : null;
    const id = await make("lot", title, {
      title, lot_no: no1, lot_seq: no2, lot_date: day(int(5, 300)),
      product_id: Number(p.id),
      work_order_id: wo ? Number(wo.id) : null,
      warehouse_id: wh ? Number(wh.id) : null,
      shelf: `R${int(1, 12)}-${int(1, 40)}`,
      quantity: money(int(200, 12000)),
      status: statuses[i % statuses.length],
    }, "lots");
    if (id) {
      await link(id, Number(p.id), "lot_product");
      if (wo) await link(id, Number(wo.id), "lot_work_order");
      if (wh) await link(id, Number(wh.id), "lot_warehouse");
    }
  }

  // --- Maliyet Dagitim ---------------------------------------------------
  // Service centres cascade into production centres. SIRA_NO is load-bearing:
  // the same percentages applied in a different order give a different unit
  // cost, which is why the sequence is stored rather than inferred.
  const byName = new Map(centers.map((c) => [c.name, Number(c.id)]));
  const allocDefs = [
    ["Idari Isler", "Uretim", 45, 1], ["Idari Isler", "Montaj", 25, 1],
    ["Idari Isler", "Depo", 15, 1], ["Idari Isler", "Sevkiyat", 15, 1],
    ["Bakim Onarim", "Uretim", 60, 2], ["Bakim Onarim", "Montaj", 40, 2],
    ["Depo", "Uretim", 55, 3], ["Depo", "Montaj", 45, 3],
    ["Kalite Kontrol", "Uretim", 70, 4], ["Kalite Kontrol", "Montaj", 30, 4],
    ["Muhasebe", "Uretim", 50, 1], ["Muhasebe", "Satis", 50, 1],
  ];
  for (const month of [1, 2]) {
    for (const [src, tgt, pct, seq] of allocDefs) {
      const sId = byName.get(src);
      const tId = byName.get(tgt);
      if (!sId || !tId) continue;
      const title = `Dagitim 2028-${String(month).padStart(2, "0")} ${src}>${tgt}`;
      const id = await make("cost-allocation", title, {
        title, period_year: 2028, period_month: month, sequence: seq,
        source_cost_center_id: sId, target_cost_center_id: tId, percent: pct,
      }, "allocations");
      if (id) {
        await link(id, sId, "allocation_source");
        await link(id, tId, "allocation_target");
      }
    }
  }

  // --- Kesin Maliyet -----------------------------------------------------
  // Time is carried next to money so a variance can be attributed to RATE or
  // to USAGE. A total alone cannot answer which.
  const prodCenters = ["Uretim", "Montaj"].map((n) => [n, byName.get(n)]).filter(([, v]) => v);
  for (let month = 1; month <= 2; month++) {
    for (let i = 0; i < 10 && i < products.length; i++) {
      const p = products[i];
      const [ccName, ccId] = prodCenters[i % prodCenters.length];
      const qty = int(500, 9000);
      const machineMin = money(qty * (0.3 + rnd() * 0.9));
      const laborMin = money(machineMin * (0.08 + rnd() * 0.25));
      const material = money(qty * (12 + rnd() * 40));
      const labor = money(laborMin * (4.5 + rnd() * 2));
      const machine = money(machineMin * (2.2 + rnd() * 1.5));
      const energy = money(machineMin * (0.9 + rnd() * 0.6));
      const overhead = money((material + labor + machine) * (0.06 + rnd() * 0.08));
      const total = money(material + labor + machine + energy + overhead);
      const title = `Maliyet 2028-${String(month).padStart(2, "0")} ${p.name}`.slice(0, 90);
      const id = await make("actual-cost", title, {
        title, period_year: 2028, period_month: month,
        product_id: Number(p.id), cost_center_id: ccId, stage: i % 2 === 0 ? 1 : 2,
        quantity: qty, machine_minutes: machineMin, labor_minutes: laborMin,
        bom_cost: material, unit_cost: money(total / qty), total_cost: total,
        cost_breakdown: {
          direct_material: material, direct_labor: labor,
          machine: machine, energy: energy, overhead: overhead,
        },
      }, "actual_costs");
      if (id) {
        await link(id, Number(p.id), "actual_cost_product");
        await link(id, ccId, "actual_cost_cost_center");
      }
    }
  }

  out.calls = calls;
  return out;
};

export default async (_c, client) => {
  const q = async (sql) => {
    const r = await client.query(sql);
    return r?.rows ?? r ?? [];
  };
  const types = await q(
    "SELECT entity_type, count(*)::int AS n FROM entities WHERE deleted_at IS NULL GROUP BY 1 ORDER BY 2 DESC",
  );
  const edges = await q(
    "SELECT rt.slug, count(*)::int AS n FROM entity_relationships r JOIN entity_relationship_types rt ON rt.id = r.relationship_type_id WHERE r.deleted_at IS NULL GROUP BY 1 ORDER BY 2 DESC",
  );
  const wo = await q(
    "SELECT count(*)::int AS n, count(metadata->>'product_id')::int AS with_product FROM entities WHERE entity_type='work-order' AND deleted_at IS NULL",
  );
  const rt = await q(
    "SELECT metadata->>'product_id' AS pid FROM entities WHERE entity_type='routing' AND deleted_at IS NULL LIMIT 5",
  );
  const woP = await q(
    "SELECT metadata->>'product_id' AS pid FROM entities WHERE entity_type='work-order' AND deleted_at IS NULL LIMIT 5",
  );
  return {
    entity_types: types.length,
    entities_total: types.reduce((a, b) => a + b.n, 0),
    by_type: types.map((t) => `${t.entity_type}:${t.n}`),
    edge_types: edges.length,
    edges_total: edges.reduce((a, b) => a + b.n, 0),
    by_edge: edges.map((e) => `${e.slug}:${e.n}`),
    work_orders: wo[0],
    routing_product_ids: rt.map((x) => x.pid),
    work_order_product_ids: woP.map((x) => x.pid),
  };
};

// `work-order` was declared but never seeded, so the production chain had no
// middle: lots pointed at no run, and no run pointed at a routing. This seeds
// work orders against the released routings, plus the warehouses / ledger
// accounts / BOMs whose edge types existed with nothing on them.
//
// Deterministic and idempotent by name; re-run until `remaining` is 0.
const BUDGET = 180;

export default async (_ctx, client) => {
  let s = 330077;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const money = (n) => Math.round(n * 100) / 100;
  const day = (o) => new Date(Date.UTC(2028, 0, 4) + o * 86400000).toISOString().slice(0, 10);

  let calls = 0;
  const out = { warehouses: 0, accounts: 0, boms: 0, work_orders: 0, edges: 0, lots_relinked: 0, errors: [], remaining: 0 };
  const note = (e) => {
    if (out.errors.length < 5) out.errors.push(String(e?.message ?? e).slice(0, 160));
  };
  const q = async (sql) => {
    calls++;
    const r = await client.query(sql);
    return r?.rows ?? r ?? [];
  };

  const taken = new Set();
  for (const t of ["work-order", "warehouse", "ledger-account", "bom"]) {
    for (const e of await q(`SELECT name FROM entities WHERE entity_type='${t}' AND deleted_at IS NULL`)) {
      taken.add(`${t}:${e.name}`);
    }
  }
  const make = async (type, name, metadata, counter) => {
    if (taken.has(`${type}:${name}`)) return null;
    if (calls + 2 > BUDGET) { out.remaining++; return null; }
    try {
      const r = await client.entities.create({ type, name, metadata });
      calls++;
      out[counter]++;
      taken.add(`${type}:${name}`);
      return Number(r.entity.id);
    } catch (e) { note(e); return null; }
  };
  const link = async (from, to, slug) => {
    if (!from || !to) return;
    if (calls + 1 > BUDGET) { out.remaining++; return; }
    try {
      await client.entities.link({ from_entity_id: from, to_entity_id: to, relationship_type_slug: slug });
      calls++;
      out.edges++;
    } catch (e) { note(e); }
  };

  // --- Ambar --------------------------------------------------------------
  for (const [title, code] of [
    ["Hammadde Ambari", "AMB-10"], ["Yari Mamul Ambari", "AMB-20"],
    ["Mamul Ambari", "AMB-30"], ["Karantina Ambari", "AMB-40"], ["Sevkiyat Ambari", "AMB-50"],
  ]) {
    await make("warehouse", title, { title, code, is_active: true }, "warehouses");
  }

  // --- Hesap Plani (Tek Duzen Hesap Plani codes) -------------------------
  for (const [title, code] of [
    ["Kasa", "100"], ["Bankalar", "102"], ["Alicilar", "120"], ["Alacak Senetleri", "121"],
    ["Ilk Madde ve Malzeme", "150"], ["Yarimamuller Uretim", "151"], ["Mamuller", "152"],
    ["Saticilar", "320"], ["Hesaplanan KDV", "391"], ["Indirilecek KDV", "191"],
    ["Yurtici Satislar", "600"], ["Satilan Mamul Maliyeti", "620"],
    ["Direkt Ilk Madde Gideri", "710"], ["Direkt Iscilik Gideri", "720"],
    ["Genel Uretim Gideri", "730"], ["Genel Yonetim Gideri", "770"],
  ]) {
    await make("ledger-account", title, { title, code, is_active: true }, "accounts");
  }

  const products = await q(
    "SELECT id, name FROM entities WHERE entity_type='product' AND deleted_at IS NULL ORDER BY id LIMIT 40",
  );
  const routings = await q(
    "SELECT id, name, metadata->>'product_id' AS pid FROM entities WHERE entity_type='routing' AND deleted_at IS NULL ORDER BY id",
  );
  const orders = await q(
    "SELECT id, metadata->>'customer_id' AS cid FROM entities WHERE entity_type='order' AND deleted_at IS NULL ORDER BY id",
  );
  const resources = await q(
    "SELECT id, name, metadata->>'catalog_class' AS cls FROM entities WHERE entity_type='resource' AND deleted_at IS NULL AND metadata->>'resource_type'='machine' ORDER BY id",
  );
  if (routings.length === 0) return { error: "seed routings first" };

  // --- Is Emri ------------------------------------------------------------
  // Statuses are spread so the demo shows a live shop floor, not a graveyard of
  // completed runs. `completed_quantity` under-runs `quantity` on purpose:
  // scrap is what makes actual cost differ from standard.
  const statusPlan = [
    "completed", "completed", "completed", "completed", "completed",
    "in_progress", "in_progress", "in_progress", "in_progress",
    "released", "released", "released", "planned", "planned", "cancelled",
  ];
  for (let i = 0; i < 20; i++) {
    const rt = routings[i % routings.length];
    const p = products.find((x) => String(x.id) === String(rt.pid));
    if (!p) continue;
    const status = statusPlan[i % statusPlan.length];
    const qty = int(500, 9000);
    const done =
      status === "completed" ? money(qty * (0.94 + rnd() * 0.05))
      : status === "in_progress" ? money(qty * (0.15 + rnd() * 0.6))
      : 0;
    const docNo = `IE2028${String(1000 + i)}`;
    const start = int(5, 300);
    const ord = orders.length ? orders[i % orders.length] : null;
    const id = await make("work-order", docNo, {
      title: docNo, document_no: docNo, status,
      date: day(start), due_date: day(start + int(7, 45)),
      product_id: Number(p.id), routing_id: Number(rt.id),
      order_id: ord ? Number(ord.id) : null,
      quantity: qty, completed_quantity: done,
      lines: [{ product_id: Number(p.id), quantity: qty, due_date: day(start + int(7, 45)), status }],
    }, "work_orders");
    if (id) {
      await link(id, Number(p.id), "work_order_product");
      await link(id, Number(rt.id), "work_order_routing");
      if (ord) await link(id, Number(ord.id), "work_order_order");
      const machine = resources.length ? resources[i % resources.length] : null;
      if (machine) await link(id, Number(machine.id), "work_order_resource");
    }
  }

  out.calls = calls;
  return out;
};

// Backfills the edges that were hollow because their target did not exist yet:
// lots had no work order and no warehouse, cost elements had no ledger account.
// Also writes the movement -> lot edge, which is what makes traceability work
// in BOTH directions — from a lot to everything it went into, and from a
// shipped invoice back to the lot.
const BUDGET = 180;

export default async (_ctx, client) => {
  let s = 51477;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

  let calls = 0;
  const out = { lot_wo: 0, lot_wh: 0, ce_acct: 0, mv_lot: 0, patched: 0, errors: [], remaining: 0 };
  const note = (e) => {
    if (out.errors.length < 5) out.errors.push(String(e?.message ?? e).slice(0, 160));
  };
  const q = async (sql) => {
    calls++;
    const r = await client.query(sql);
    return r?.rows ?? r ?? [];
  };
  const link = async (from, to, slug) => {
    if (!from || !to) return;
    if (calls + 1 > BUDGET) { out.remaining++; return false; }
    try {
      await client.entities.link({ from_entity_id: from, to_entity_id: to, relationship_type_slug: slug });
      calls++;
      return true;
    } catch (e) { note(e); return false; }
  };

  const lots = await q(
    "SELECT id, metadata FROM entities WHERE entity_type='lot' AND deleted_at IS NULL ORDER BY id",
  );
  const wos = await q(
    "SELECT id, metadata->>'product_id' AS pid FROM entities WHERE entity_type='work-order' AND deleted_at IS NULL ORDER BY id",
  );
  const whs = await q(
    "SELECT id FROM entities WHERE entity_type='warehouse' AND deleted_at IS NULL ORDER BY id",
  );
  const ces = await q(
    "SELECT id, metadata->>'code' AS code FROM entities WHERE entity_type='cost-element' AND deleted_at IS NULL ORDER BY id",
  );
  const accts = await q(
    "SELECT id, metadata->>'code' AS code FROM entities WHERE entity_type='ledger-account' AND deleted_at IS NULL",
  );
  const movements = await q(
    "SELECT id, metadata->>'product_id' AS pid FROM entities WHERE entity_type='stock-movement' AND deleted_at IS NULL ORDER BY id",
  );

  // A work order per product, so a lot lands on a run that actually made it.
  const woByProduct = new Map();
  for (const w of wos) {
    if (!woByProduct.has(String(w.pid))) woByProduct.set(String(w.pid), Number(w.id));
  }
  const acctByCode = new Map(accts.map((a) => [a.code, Number(a.id)]));
  // Cost element -> the TDHP account it posts to. Named, not positional: an
  // index-based pairing would silently re-map when the chart grows.
  const ceToAcct = {
    "MK-710": "710", "MK-720": "720", "MK-730": "730",
    "MK-740": "730", "MK-750": "730", "MK-760": "730",
  };

  for (const l of lots) {
    const m = typeof l.metadata === "string" ? JSON.parse(l.metadata) : (l.metadata ?? {});
    const woId = woByProduct.get(String(m.product_id)) ?? (wos.length ? Number(wos[0].id) : null);
    const whId = whs.length ? Number(whs[Number(l.id) % whs.length].id) : null;
    if (await link(Number(l.id), woId, "lot_work_order")) out.lot_wo++;
    if (await link(Number(l.id), whId, "lot_warehouse")) out.lot_wh++;
    // The stored ids were 0 (null coerced by the integer schema); patch them so
    // the form renders a label instead of a dangling zero.
    if ((!m.work_order_id || m.work_order_id === 0) && woId) {
      try {
        await client.entities.update({
          entity_id: Number(l.id),
          metadata: { ...m, work_order_id: woId, warehouse_id: whId ?? m.warehouse_id },
        });
        calls++;
        out.patched++;
      } catch (e) { note(e); }
    }
  }

  for (const ce of ces) {
    const acct = acctByCode.get(ceToAcct[ce.code]);
    if (await link(Number(ce.id), acct, "cost_element_account")) out.ce_acct++;
  }

  // movement -> lot, matched on product so the trace is real, not decorative.
  const lotByProduct = new Map();
  for (const l of lots) {
    const m = typeof l.metadata === "string" ? JSON.parse(l.metadata) : (l.metadata ?? {});
    const k = String(m.product_id);
    if (!lotByProduct.has(k)) lotByProduct.set(k, []);
    lotByProduct.get(k).push(Number(l.id));
  }
  for (const mv of movements) {
    if (calls + 2 > BUDGET) { out.remaining++; break; }
    const cands = lotByProduct.get(String(mv.pid));
    if (!cands || cands.length === 0) continue;
    if (await link(Number(mv.id), cands[int(0, cands.length - 1)], "movement_lot")) out.mv_lot++;
  }

  out.calls = calls;
  return out;
};

