// --- Behaviors --------------------------------------------------------------
//
// The open architectural question is whether a Behavior can post an invoice AND
// emit its journal entry in ONE commit. If it can, Behavior-as-writer covers the
// accounting case and no in-transaction hook framework is needed for it. If it
// cannot, a post-commit reaction gives "journal entry late, or never", and a
// posted invoice with no journal entry is an accounting problem, not a retry
// problem.
//
// Two entity outputs, deliberately: `promoteBehaviorEntityOutput` takes the
// window-completion `tx`, so either both outputs land or neither does.

const postInvoiceRun = defineBehavior({
	slug: "post-invoice-with-journal",
	agent: agent,
	name: "Fatura Muhasebelestirme",
	description:
		"Posts draft invoices and emits the matching double-entry journal entry as a second declared output, to test whether both land in one commit.",
	prompt: [
		"For each invoice row in the `drafts` source, produce exactly one row in EACH output.",
