		"  journal_no = 'YEV' + invoice_no, date = the invoice date,",
		"  description = 'Satis faturasi ' + invoice_no,",
		"  lines = three entries against the chart of accounts:",
		"    120 Alicilar        debit  = grand_total, credit = 0",
