// Fire the two-output Behavior and record the run id. The question under test:
// do a Behavior's TWO declared entity outputs land in ONE commit? If they do,
// "post the invoice AND emit its journal entry" is atomic today and needs no
// in-transaction hook.
export default async (_c, client) => {
  const { behaviors } = await client.behaviors.list();
  const b = (behaviors ?? []).find((x) => x.slug === "post-invoice-with-journal");
  if (!b) return { error: "behavior not found", slugs: (behaviors ?? []).map((x) => x.slug) };
  const before = await client.query(
    "SELECT entity_type, count(*)::int AS n FROM entities WHERE entity_type IN ('invoice-posting','journal-entry') AND deleted_at IS NULL GROUP BY 1",
  );
  const r = await client.behaviors.trigger({ behavior_id: b.id });
  return {
    behavior_id: b.id,
    before: (before?.rows ?? before ?? []).map((x) => `${x.entity_type}:${x.n}`),
    trigger: r,
  };
};

