// Fills the two declared-but-empty types that made other things hollow:
//
// - `bom` (RECETE). Without it `actual-cost.bom_cost` is a number with nothing
//   behind it, and a work order consumes materials nobody declared.
// - `journal-entry` (MUHASEBE yevmiye). Without it the "where does it hit the
//   books" edge group is empty, so the document chain stops at the invoice.
//
// The journal entries are seeded DIRECTLY rather than produced by the posting
// Behavior, because an unattended Behavior run dies on a tool-approval card
// before window completion. That is a real gap, not a shortcut — these rows
// stand in for output the Behavior should have emitted.
//
// Deterministic and idempotent by name; re-run until `remaining` is 0.
const BUDGET = 180;

export default async (_ctx, client) => {
  let s = 618203;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const money = (n) => Math.round(n * 100) / 100;

  let calls = 0;
  const out = { boms: 0, journals: 0, edges: 0, unbalanced: 0, errors: [], remaining: 0 };
  const note = (e) => {
    if (out.errors.length < 6) out.errors.push(String(e?.message ?? e).slice(0, 160));
  };
  const q = async (sql) => {
    calls++;
    const r = await client.query(sql);
    return r?.rows ?? r ?? [];
  };
  const taken = new Set();
  for (const t of ["bom", "journal-entry"]) {
    for (const e of await q(`SELECT name FROM entities WHERE entity_type='${t}' AND deleted_at IS NULL`)) {
      taken.add(`${t}:${e.name}`);
    }
  }
  const make = async (type, name, metadata, counter) => {
    if (taken.has(`${type}:${name}`)) return null;
    if (calls + 2 > BUDGET) { out.remaining++; return null; }
    try {
      const r = await client.entities.create({ type, name, metadata });
      calls++;
      out[counter]++;
      taken.add(`${type}:${name}`);
      return Number(r.entity.id);
    } catch (e) { note(e); return null; }
  };
  const link = async (from, to, slug) => {
    if (!from || !to) return;
    if (calls + 1 > BUDGET) { out.remaining++; return; }
    try {
      await client.entities.link({ from_entity_id: from, to_entity_id: to, relationship_type_slug: slug });
      calls++;
      out.edges++;
    } catch (e) { note(e); }
  };

  // --- Recete -------------------------------------------------------------
  // Finished goods are the products that have a routing; everything else is
  // treated as raw material. That keeps the BOM from listing a finished part
  // as its own component.
  const routed = await q(
    "SELECT DISTINCT (metadata->>'product_id')::int AS pid FROM entities WHERE entity_type='routing' AND deleted_at IS NULL AND metadata->>'product_id' IS NOT NULL",
  );
  const finishedIds = new Set(routed.map((r) => Number(r.pid)));
  const products = await q(
    "SELECT id, name, metadata->>'unit' AS unit FROM entities WHERE entity_type='product' AND deleted_at IS NULL ORDER BY id",
  );
  const finished = products.filter((p) => finishedIds.has(Number(p.id)));
  const raw = products.filter((p) => !finishedIds.has(Number(p.id)));
  if (finished.length === 0 || raw.length < 4) return { error: "seed routings and products first" };

  for (let i = 0; i < finished.length; i++) {
    const fp = finished[i];
    const title = `Recete ${fp.name}`.slice(0, 90);
    const n = int(2, 4);
    const components = [];
    for (let k = 0; k < n; k++) {
      const rp = raw[(i * 3 + k * 5) % raw.length];
      if (components.some((c) => c.product_id === Number(rp.id))) continue;
      components.push({
        product_id: Number(rp.id),
        quantity: money(0.2 + rnd() * 4),
        // Scrap is what makes actual cost diverge from the recipe, so it is
        // stated per component rather than as one number on the header.
        scrap_rate: money(rnd() * 6),
      });
    }
    const id = await make("bom", title, {
      title, product_id: Number(fp.id), version: "1.0", output_quantity: 1, components,
    }, "boms");
    if (id) {
      await link(id, Number(fp.id), "bom_product");
      for (const c of components) await link(id, c.product_id, "bom_component");
    }
  }

  // --- Yevmiye Fisi -------------------------------------------------------
  // Turkish domestic sale, 20% KDV:
  //   120 Alicilar          DEBIT  grand_total
  //   600 Yurtici Satislar  CREDIT grand_total / 1.20
  //   391 Hesaplanan KDV    CREDIT the remainder
  // The VAT line is the REMAINDER, never a second rounded division — rounding
  // both legs independently is how a one-kurus imbalance gets into the books.
  const accts = await q(
    "SELECT id, metadata->>'code' AS code FROM entities WHERE entity_type='ledger-account' AND deleted_at IS NULL",
  );
  const acct = new Map(accts.map((a) => [a.code, Number(a.id)]));
  const AR = acct.get("120");
  const REV = acct.get("600");
  const VAT = acct.get("391");
  if (!AR || !REV || !VAT) return { ...out, error: "chart of accounts missing 120/600/391" };

  const invoices = await q(
    "SELECT id, name, metadata->>'document_no' AS doc, metadata->>'date' AS date, (metadata->>'customer_id')::int AS cust, (metadata->>'grand_total')::numeric AS gt, metadata->>'status' AS status FROM entities WHERE entity_type='invoice' AND deleted_at IS NULL AND metadata->>'status' IN ('issued','posted') ORDER BY id",
  );
  for (const inv of invoices) {
    const gt = money(Number(inv.gt));
    const base = money(gt / 1.2);
    const vat = money(gt - base);
    const docNo = `YEV${inv.doc}`;
    const lines = [
      { account_id: AR, description: `${inv.doc} Alicilar`, debit: gt, credit: 0 },
      { account_id: REV, description: `${inv.doc} Yurtici Satis`, debit: 0, credit: base },
      { account_id: VAT, description: `${inv.doc} Hesaplanan KDV`, debit: 0, credit: vat },
    ];
    const dr = money(lines.reduce((a, l) => a + l.debit, 0));
    const cr = money(lines.reduce((a, l) => a + l.credit, 0));
    if (dr !== cr) { out.unbalanced++; continue; }

    const id = await make("journal-entry", docNo, {
      title: docNo, document_no: docNo, status: "posted", date: inv.date,
      description: `Satis faturasi ${inv.doc}`,
      lines, total_debit: dr, total_credit: cr,
    }, "journals");
    if (id) {
      await link(Number(inv.id), id, "invoice_journal");
      await link(id, AR, "journal_account");
      if (inv.cust) await link(id, Number(inv.cust), "journal_customer");
      await link(Number(inv.id), REV, "invoice_account");
    }
  }

  out.calls = calls;
  return out;
};

// Do the seeded books actually balance, and is the ledger edge group non-empty?
export default async (_c, client) => {
  const q = async (sql) => {
    const r = await client.query(sql);
    return r?.rows ?? r ?? [];
  };
  const je = await q(
    "SELECT name, (metadata->>'total_debit')::numeric AS dr, (metadata->>'total_credit')::numeric AS cr, jsonb_array_length(metadata->'lines') AS n FROM entities WHERE entity_type='journal-entry' AND deleted_at IS NULL ORDER BY name",
  );
  const lineSum = await q(
    `SELECT e.name,
            round(sum((l->>'debit')::numeric), 2) AS line_dr,
            round(sum((l->>'credit')::numeric), 2) AS line_cr
     FROM entities e, jsonb_array_elements(e.metadata->'lines') l
     WHERE e.entity_type='journal-entry' AND e.deleted_at IS NULL
     GROUP BY e.name ORDER BY e.name`,
  );
  const bySum = new Map(lineSum.map((r) => [r.name, r]));
  const bom = await q(
    "SELECT count(*)::int AS n, sum(jsonb_array_length(metadata->'components'))::int AS components FROM entities WHERE entity_type='bom' AND deleted_at IS NULL",
  );
  const ledgerEdges = await q(
    "SELECT rt.slug, count(*)::int AS n FROM entity_relationships r JOIN entity_relationship_types rt ON rt.id=r.relationship_type_id WHERE r.deleted_at IS NULL AND rt.slug IN ('invoice_journal','journal_account','journal_customer','invoice_account','payment_journal','cheque_account','bom_product','bom_component') GROUP BY 1 ORDER BY 1",
  );
  const totals = await q(
    "SELECT count(*)::int AS entities FROM entities WHERE deleted_at IS NULL",
  );
  const edgeTotal = await q(
    "SELECT count(*)::int AS edges FROM entity_relationships WHERE deleted_at IS NULL",
  );
  const empty = await q(
    `SELECT et.slug FROM entity_types et
     LEFT JOIN entities e ON e.entity_type_id = et.id AND e.deleted_at IS NULL
     WHERE et.organization_id IS NOT NULL AND et.slug NOT LIKE '$%'
     GROUP BY et.slug HAVING count(e.id) = 0 ORDER BY et.slug`,
  );
  return {
    journal_entries: je.map((r) => {
      const ls = bySum.get(r.name);
      const ok =
        Number(r.dr) === Number(r.cr) &&
        Number(ls?.line_dr) === Number(r.dr) &&
        Number(ls?.line_cr) === Number(r.cr);
      return `${r.name} lines=${r.n} dr=${r.dr} cr=${r.cr} lineDr=${ls?.line_dr} lineCr=${ls?.line_cr} ${ok ? "BALANCED" : "*** OFF ***"}`;
    }),
    bom: bom[0],
    ledger_and_bom_edges: ledgerEdges.map((e) => `${e.slug}:${e.n}`),
    entities_total: totals[0]?.entities,
    edges_total: edgeTotal[0]?.edges,
    still_empty_types: empty.map((r) => r.slug),
  };
};

