/**
 * SPIKE — edges as a claim set plus an append-only change log.
 *
 * The design: every assertion and retraction is recorded in the log (what
 * changed and how); `entity_relationships` stays the projection holding current
 * state (what is true now, at index speed).
 *
 * This is NOT a new architecture. Entity *field* changes already work this way —
 * `recordChangeEvent` writes a field-level diff into `events` with
 * `semantic_type='change'` while the entity row holds current state. Edges are
 * the hole in that pattern: on origin/main `recordChangeEvent` has exactly one
 * call site (`manage_entity.ts:574`, inside `handleUpdate`), and `handleLink`,
 * `handleUnlink` and `handleUpdateLink` record nothing at all.
 *
 * The one novel piece is WHERE current claim state lives. Folding the whole log
 * to answer "is this edge live" would be an aggregate over history, which the
 * read path forbids and which grows without bound. So the projection row carries
 * its own claim set in `metadata.claims`, keyed by owner — bounded by the number
 * of owners, never by history length. The log is written for audit and replay
 * and is never read to decide current state.
 */
import type { DbClient } from '../db/client';
import { getDb } from '../db/client';
import { insertConnectionlessAuditEvent } from './insert-event';

/** `semantic_type` for an edge change, mirroring the existing `'change'`. */
export const EDGE_CHANGE_SEMANTIC_TYPE = 'edge_change';

export type EdgeClaimRef = {
  orgId: string;
  fromEntityId: number;
  toEntityId: number;
  relationshipTypeId: number;
  /** Stable owner identity — a connector rule, a user, an agent. */
  ownerId: string;
};

export type ClaimOutcome = {
  /** Live after this operation. */
  live: boolean;
  /** Owners currently asserting this edge. */
  owners: string[];
  /** The projection changed state (created or tombstoned), rather than only its claim set. */
  flipped: boolean;
};

function claimsOf(metadata: unknown): string[] {
  const claims = (metadata as { claims?: Record<string, unknown> } | null)?.claims;
  return claims ? Object.keys(claims).sort() : [];
}

/**
 * Append the change to the log. Uses `insertConnectionlessAuditEvent`, which
 * AWAITS and throws — deliberately not `recordChangeEvent`, which is
 * fire-and-forget (retries twice, then logs an error and drops the row). Audit
 * can tolerate a dropped row; a claim log cannot, because a dropped assertion
 * silently becomes a lost edge.
 */
async function logEdgeChange(params: {
  ref: EdgeClaimRef;
  op: 'assert' | 'retract';
  before: string[];
  after: string[];
  ruleVersion?: string;
  seq: string;
}): Promise<void> {
  const { ref } = params;
  await insertConnectionlessAuditEvent({
    organizationId: ref.orgId,
    entityIds: [ref.fromEntityId, ref.toEntityId],
    // Idempotency is keyed on the caller-supplied sequence token, so a retried
    // batch does not append a second identical history row.
    originId: `edge:${ref.fromEntityId}:${ref.toEntityId}:${ref.relationshipTypeId}:${ref.ownerId}:${params.seq}`,
    semanticType: EDGE_CHANGE_SEMANTIC_TYPE,
    title: `${params.op} ${ref.fromEntityId}->${ref.toEntityId}`,
    metadata: {
      op: params.op,
      ownerId: ref.ownerId,
      fromEntityId: String(ref.fromEntityId),
      toEntityId: String(ref.toEntityId),
      relationshipTypeId: String(ref.relationshipTypeId),
      ruleVersion: params.ruleVersion ?? null,
      // The diff, in the same spirit as `recordChangeEvent`'s
      // `metadata.changes = [{field, old, new}]`.
      changes: [{ field: 'claims', old: params.before, new: params.after }],
    },
  });
}

/**
 * Record that `ownerId` asserts this edge. Idempotent per owner: asserting twice
 * leaves one claim.
 *
 * The claim-set mutation is ONE statement, so concurrent owners serialize on the
 * projection row's lock rather than racing a read-modify-write.
 */
export async function assertEdgeClaim(params: {
  ref: EdgeClaimRef;
  ruleVersion?: string;
  createdBy: string;
  seq: string;
  sql?: DbClient;
}): Promise<ClaimOutcome> {
  const run = async (sql: DbClient): Promise<ClaimOutcome> => {
    const { ref } = params;
    const claimValue = { ruleVersion: params.ruleVersion ?? null };

    const before = await sql<{ metadata: unknown }[]>`
      SELECT metadata FROM entity_relationships
      WHERE organization_id = ${ref.orgId}
        AND from_entity_id = ${ref.fromEntityId}
        AND to_entity_id = ${ref.toEntityId}
        AND relationship_type_id = ${ref.relationshipTypeId}
        AND deleted_at IS NULL
      FOR UPDATE
    `;
    const beforeOwners = before.length > 0 ? claimsOf(before[0].metadata) : [];

    const rows = await sql<{ metadata: unknown }[]>`
      INSERT INTO entity_relationships (
        organization_id, from_entity_id, to_entity_id, relationship_type_id,
        metadata, confidence, source, created_by, updated_by, created_at, updated_at
      ) VALUES (
        ${ref.orgId}, ${ref.fromEntityId}, ${ref.toEntityId}, ${ref.relationshipTypeId},
        ${sql.json({ claims: { [ref.ownerId]: claimValue } })},
        1.0, 'feed', ${params.createdBy}, ${params.createdBy},
        current_timestamp, current_timestamp
      )
      ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
        WHERE deleted_at IS NULL
      DO UPDATE SET
        metadata = jsonb_set(
          coalesce(entity_relationships.metadata, '{}'::jsonb),
          ARRAY['claims', ${ref.ownerId}],
          ${sql.json(claimValue)},
          true
        ),
        updated_by = ${params.createdBy},
        updated_at = current_timestamp
      RETURNING metadata
    `;
    const afterOwners = claimsOf(rows[0]?.metadata);
    await logEdgeChange({
      ref,
      op: 'assert',
      before: beforeOwners,
      after: afterOwners,
      ruleVersion: params.ruleVersion,
      seq: params.seq,
    });
    return { live: true, owners: afterOwners, flipped: beforeOwners.length === 0 };
  };
  return params.sql ? run(params.sql) : (getDb().begin(run) as Promise<ClaimOutcome>);
}

/**
 * Withdraw `ownerId`'s claim. The edge is tombstoned only when the LAST claim
 * goes — which is the whole point: one owner withdrawing must not destroy an
 * edge another owner still asserts.
 */
export async function retractEdgeClaim(params: {
  ref: EdgeClaimRef;
  seq: string;
  sql?: DbClient;
}): Promise<ClaimOutcome> {
  const run = async (sql: DbClient): Promise<ClaimOutcome> => {
    const { ref } = params;
    const before = await sql<{ metadata: unknown }[]>`
      SELECT metadata FROM entity_relationships
      WHERE organization_id = ${ref.orgId}
        AND from_entity_id = ${ref.fromEntityId}
        AND to_entity_id = ${ref.toEntityId}
        AND relationship_type_id = ${ref.relationshipTypeId}
        AND deleted_at IS NULL
      FOR UPDATE
    `;
    if (before.length === 0) return { live: false, owners: [], flipped: false };
    const beforeOwners = claimsOf(before[0].metadata);

    // Remove this owner's key, and tombstone in the SAME statement iff nothing
    // remains. Column references on the right-hand side see the pre-update row,
    // so the emptiness test is evaluated against the old claim set.
    const rows = await sql<{ metadata: unknown; deleted_at: string | null }[]>`
      UPDATE entity_relationships
      SET metadata = jsonb_set(
            coalesce(metadata, '{}'::jsonb),
            ARRAY['claims'],
            coalesce(metadata -> 'claims', '{}'::jsonb) - ${ref.ownerId},
            true
          ),
          deleted_at = CASE
            WHEN (coalesce(metadata -> 'claims', '{}'::jsonb) - ${ref.ownerId}) = '{}'::jsonb
            THEN current_timestamp ELSE NULL END,
          updated_at = current_timestamp
      WHERE organization_id = ${ref.orgId}
        AND from_entity_id = ${ref.fromEntityId}
        AND to_entity_id = ${ref.toEntityId}
        AND relationship_type_id = ${ref.relationshipTypeId}
        AND deleted_at IS NULL
      RETURNING metadata, deleted_at
    `;
    const afterOwners = claimsOf(rows[0]?.metadata);
    const live = rows[0]?.deleted_at == null;
    await logEdgeChange({
      ref,
      op: 'retract',
      before: beforeOwners,
      after: afterOwners,
      seq: params.seq,
    });
    return { live, owners: afterOwners, flipped: live === false };
  };
  return params.sql ? run(params.sql) : (getDb().begin(run) as Promise<ClaimOutcome>);
}

export type EdgeHistoryEntry = {
  op: string;
  ownerId: string;
  before: string[];
  after: string[];
  occurredAt: string;
};

/**
 * Read the change history for one edge. AUDIT ONLY — never a read path. Current
 * state comes from the projection row's claim set, which is why this can be a
 * full history scan without violating the no-aggregate-on-read rule.
 */
export async function readEdgeHistory(params: {
  orgId: string;
  fromEntityId: number;
  toEntityId: number;
  relationshipTypeId: number;
  sql?: DbClient;
}): Promise<EdgeHistoryEntry[]> {
  const sql = params.sql ?? getDb();
  const rows = await sql<
    {
      op: string;
      owner_id: string;
      changes: Array<{ old: string[]; new: string[] }>;
      occurred_at: string;
    }[]
  >`
    SELECT metadata ->> 'op' AS op,
           metadata ->> 'ownerId' AS owner_id,
           metadata -> 'changes' AS changes,
           occurred_at
    FROM events
    WHERE organization_id = ${params.orgId}
      AND semantic_type = ${EDGE_CHANGE_SEMANTIC_TYPE}
      AND metadata ->> 'fromEntityId' = ${String(params.fromEntityId)}
      AND metadata ->> 'toEntityId' = ${String(params.toEntityId)}
      AND metadata ->> 'relationshipTypeId' = ${String(params.relationshipTypeId)}
    ORDER BY id ASC
  `;
  return rows.map((r) => ({
    op: r.op,
    ownerId: r.owner_id,
    before: r.changes?.[0]?.old ?? [],
    after: r.changes?.[0]?.new ?? [],
    occurredAt: r.occurred_at,
  }));
}

/**
 * SPIKE — does the claim-set + change-log design actually retire the defect that
 * one relationship row cannot hold two independent claims?
 *
 * The red test in `declared-edges-codex-findings.test.ts` says owner A
 * retracting destroys owner B's still-valid edge. If this design is right, the
 * same sequence must leave the edge live.
 */
import { beforeEach, describe, expect, it } from 'vitest';
import { cleanupTestDatabase, getTestDb } from '../../__tests__/setup/test-db';
import {
  addUserToOrganization,
  createTestOrganization,
  createTestUser,
} from '../../__tests__/setup/test-fixtures';
import {
  assertEdgeClaim,
  type EdgeClaimRef,
  readEdgeHistory,
  retractEdgeClaim,
} from '../edge-claims-spike';
import { ensureMemberEntityType } from '../member-entity-type';

async function setup() {
  await cleanupTestDatabase();
  const org = await createTestOrganization({ name: 'claims org' });
  const user = await createTestUser();
  await addUserToOrganization(user.id, org.id, 'owner');
  await ensureMemberEntityType(org.id);
  const sql = getTestDb();

  const [etype] = await sql<{ id: number }[]>`
    SELECT id FROM entity_types WHERE organization_id = ${org.id} AND slug = '$member' LIMIT 1
  `;
  const mk = async (name: string) => {
    const [row] = await sql<{ id: number }[]>`
      INSERT INTO entities (organization_id, entity_type_id, name, slug, metadata, created_by, created_at, updated_at)
      VALUES (${org.id}, ${Number(etype.id)}, ${name}, ${name}, '{}'::jsonb, ${user.id},
              current_timestamp, current_timestamp)
      RETURNING id
    `;
    return Number(row.id);
  };
  const invoice = await mk('FTR-1');
  const customer = await mk('CARI-1');
  const [typeRow] = await sql<{ id: number }[]>`
    INSERT INTO entity_relationship_types (organization_id, slug, name, status, created_at, updated_at)
    VALUES (${org.id}, 'invoice_customer', 'invoice_customer', 'active', current_timestamp, current_timestamp)
    RETURNING id
  `;

  const ref = (ownerId: string): EdgeClaimRef => ({
    orgId: org.id,
    fromEntityId: invoice,
    toEntityId: customer,
    relationshipTypeId: Number(typeRow.id),
    ownerId,
  });
  return { org, user, sql, invoice, customer, typeId: Number(typeRow.id), ref };
}

async function liveCount(orgId: string): Promise<number> {
  const sql = getTestDb();
  const [row] = await sql<{ count: string }[]>`
    SELECT COUNT(*)::text AS count FROM entity_relationships
    WHERE organization_id = ${orgId} AND deleted_at IS NULL
  `;
  return Number(row.count);
}

describe('SPIKE: edges as a claim set with an append-only change log', () => {
  beforeEach(async () => {
    await cleanupTestDatabase();
  });

  it('one owner retracting does NOT destroy an edge another owner still asserts', async () => {
    const { org, user, ref } = await setup();

    const a = await assertEdgeClaim({
      ref: ref('erp_rule'), ruleVersion: '1', createdBy: user.id, seq: 's1',
    });
    expect(a).toMatchObject({ live: true, owners: ['erp_rule'], flipped: true });

    // A second, independent owner asserts the SAME triple.
    const b = await assertEdgeClaim({
      ref: ref('human'), createdBy: user.id, seq: 's2',
    });
    expect(b.live).toBe(true);
    expect(b.owners).toEqual(['erp_rule', 'human']);
    // Still ONE projection row — the graph did not gain a duplicate edge.
    expect(await liveCount(org.id)).toBe(1);

    // The ERP rule is removed. THIS is the sequence that destroyed the edge
    // under the single-provenance design.
    const afterA = await retractEdgeClaim({ ref: ref('erp_rule'), seq: 's3' });
    expect(afterA.live).toBe(true);
    expect(afterA.owners).toEqual(['human']);
    expect(await liveCount(org.id)).toBe(1);

    // The last claim goes: now the edge is withdrawn.
    const afterB = await retractEdgeClaim({ ref: ref('human'), seq: 's4' });
    expect(afterB.live).toBe(false);
    expect(afterB.owners).toEqual([]);
    expect(await liveCount(org.id)).toBe(0);
  });

  it('asserting twice from one owner is idempotent', async () => {
    const { org, user, ref } = await setup();
    await assertEdgeClaim({ ref: ref('erp_rule'), createdBy: user.id, seq: 's1' });
    const again = await assertEdgeClaim({ ref: ref('erp_rule'), createdBy: user.id, seq: 's2' });
    expect(again.owners).toEqual(['erp_rule']);
    expect(again.flipped).toBe(false);
    expect(await liveCount(org.id)).toBe(1);

    // And one retraction still clears it — a double assert must not require two.
    const gone = await retractEdgeClaim({ ref: ref('erp_rule'), seq: 's3' });
    expect(gone.live).toBe(false);
    expect(await liveCount(org.id)).toBe(0);
  });

  it('the log records what changed and how, in order', async () => {
    const { org, user, invoice, customer, typeId, ref } = await setup();
    await assertEdgeClaim({ ref: ref('erp_rule'), ruleVersion: '1', createdBy: user.id, seq: 's1' });
    await assertEdgeClaim({ ref: ref('human'), createdBy: user.id, seq: 's2' });
    await retractEdgeClaim({ ref: ref('erp_rule'), seq: 's3' });

    const history = await readEdgeHistory({
      orgId: org.id,
      fromEntityId: invoice,
      toEntityId: customer,
      relationshipTypeId: typeId,
    });
    expect(history).toHaveLength(3);
    expect(history.map((h) => [h.op, h.ownerId])).toEqual([
      ['assert', 'erp_rule'],
      ['assert', 'human'],
      ['retract', 'erp_rule'],
    ]);
    // Each entry carries the before/after claim set — "what changed and how".
    expect(history[0]).toMatchObject({ before: [], after: ['erp_rule'] });
    expect(history[1]).toMatchObject({ before: ['erp_rule'], after: ['erp_rule', 'human'] });
    expect(history[2]).toMatchObject({ before: ['erp_rule', 'human'], after: ['human'] });
  });

  it('history survives the edge being fully withdrawn', async () => {
    const { org, user, invoice, customer, typeId, ref } = await setup();
    await assertEdgeClaim({ ref: ref('erp_rule'), createdBy: user.id, seq: 's1' });
    await retractEdgeClaim({ ref: ref('erp_rule'), seq: 's2' });
    expect(await liveCount(org.id)).toBe(0);

    // The projection is gone; the log is not. This is the property the design
    // exists for — "we can see what changed and how" after the fact.
    const history = await readEdgeHistory({
      orgId: org.id,
      fromEntityId: invoice,
      toEntityId: customer,
      relationshipTypeId: typeId,
    });
    expect(history.map((h) => h.op)).toEqual(['assert', 'retract']);
  });

  it('concurrent owners asserting the same edge both survive', async () => {
    // The read-modify-write hazard: two owners adding a key to one JSONB claim
    // set. Both keys must be present afterwards.
    const { org, user, ref } = await setup();
    await Promise.all([
      assertEdgeClaim({ ref: ref('owner_a'), createdBy: user.id, seq: 'a1' }),
      assertEdgeClaim({ ref: ref('owner_b'), createdBy: user.id, seq: 'b1' }),
      assertEdgeClaim({ ref: ref('owner_c'), createdBy: user.id, seq: 'c1' }),
    ]);

    const sql = getTestDb();
    const [row] = await sql<{ owners: string[] }[]>`
      SELECT ARRAY(SELECT jsonb_object_keys(metadata -> 'claims') ORDER BY 1) AS owners
      FROM entity_relationships
      WHERE organization_id = ${org.id} AND deleted_at IS NULL
    `;
    expect(row.owners).toEqual(['owner_a', 'owner_b', 'owner_c']);
    expect(await liveCount(org.id)).toBe(1);
  });

  it('retracting an owner that never claimed leaves the edge alone', async () => {
    const { org, user, ref } = await setup();
    await assertEdgeClaim({ ref: ref('erp_rule'), createdBy: user.id, seq: 's1' });
    const noop = await retractEdgeClaim({ ref: ref('someone_else'), seq: 's2' });
    expect(noop.live).toBe(true);
    expect(noop.owners).toEqual(['erp_rule']);
    expect(await liveCount(org.id)).toBe(1);
  });
});

