/**
 * Sources a caller may set through the MCP link/update_link surface. These say
 * only how an edge was authored; nothing reconciles against them.
 */
const CALLER_SETTABLE_SOURCES = ['ui', 'llm', 'feed', 'api'] as const;

export const EDGE_SOURCE_CONFIG = 'config';
export const EDGE_SOURCE_MANUAL = 'manual';

/**
 * Sources that mark an edge as OWNED by a reconciling subsystem.
 *
 * `channel-about` deletes the config-derived about-edges a connection no longer
 * wants by selecting exactly `source = 'config'`, and the manual ones by
 * `source = 'manual'`. So for these values `source` is not a label, it is the
 * ownership scope a sweep runs against — which is why a caller must not be able
 * to set one, or to move an edge out of one.
 */
export const OWNERSHIP_SCOPED_SOURCES = [EDGE_SOURCE_CONFIG, EDGE_SOURCE_MANUAL] as const;

/** Every value legitimately stored in `entity_relationships.source`. */
export const RELATIONSHIP_SOURCES = [
  ...CALLER_SETTABLE_SOURCES,
  ...OWNERSHIP_SCOPED_SOURCES,
] as const;

type CallerSettableSource = (typeof CALLER_SETTABLE_SOURCES)[number];

