/**
 * Validate a caller-supplied source.
 *
 * Deliberately narrower than `RELATIONSHIP_SOURCES`: the ownership-scoped
 * values are reachable only by the subsystem that reconciles them. Letting a
 * caller stamp `'config'` onto an arbitrary edge would enrol that edge in the
 * connection's config sweep, which deletes everything it did not put there.
 */
export function validateSource(source: string | undefined | null): void {
  if (source === undefined || source === null) return;
  if (!CALLER_SETTABLE_SOURCES.includes(source as CallerSettableSource)) {
    throw new Error(
      `Invalid source "${source}". Must be one of: ${CALLER_SETTABLE_SOURCES.join(', ')}`
    );
  }
}

/**
 * Refuse to move an edge out of an ownership scope.
 *
 * `update_link` COALESCEs a new source over the old one. Applied to an edge
 * owned by `channel-about`, that silently orphans it: it no longer matches the
 * `source = 'config'` sweep that would retire it, and no other sweep claims it,
 * so it outlives the configuration that created it with nothing left to clean
 * it up.
 */
export function validateSourceReassignment(
  current: string | null | undefined,
  next: string | undefined | null
): void {
  if (next === undefined || next === null || next === current) return;
  if (!OWNERSHIP_SCOPED_SOURCES.includes(current as (typeof OWNERSHIP_SCOPED_SOURCES)[number])) {
    return;
  }
  throw new Error(
    `Cannot change source of a "${current}"-owned relationship. It is reconciled by the subsystem that created it; edit that configuration instead.`
  );
}

