/**
 * `entity_relationships.source` is two vocabularies wearing one column.
 *
 * For `'ui' | 'llm' | 'feed' | 'api'` it is a label: how the edge was authored,
 * read by nothing. For `'config'` and `'manual'` it is an ownership scope —
 * `channel-about` retires the about-edges a connection no longer wants by
 * selecting exactly `source = 'config'`, and the hand-drawn ones by
 * `source = 'manual'`.
 *
 * The validator only ever knew the first four, so the second pair was
 * simultaneously unsettable through the MCP surface and silently overwritable
 * by it. These tests pin both halves.
 */

import { beforeAll, describe, expect, it } from 'vitest';
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import { TestWorkspace } from '../../setup/test-mcp-client';
import {
  EDGE_SOURCE_CONFIG,
  EDGE_SOURCE_MANUAL,
  RELATIONSHIP_SOURCES,
} from '../../../utils/relationship-validation';

describe('relationship source vocabulary', () => {
  let workspace: TestWorkspace;
  let relationshipSlug: string;

  beforeAll(async () => {
    await cleanupTestDatabase();
    workspace = await TestWorkspace.create({ name: 'Source Vocab Org' });
    await workspace.owner.entity_schema.createType({ slug: 'doc', name: 'Doc' });
    relationshipSlug = 'doc-doc';
    await workspace.owner.entity_schema.createRelType({
      slug: relationshipSlug,
      name: 'Doc Doc',
    });
  });

  async function seedEdge(prefix: string, source?: string) {
    const a = (await workspace.owner.entities.create({
      type: 'doc',
      name: `${prefix} A`,
    })) as { entity: { id: number } };
    const b = (await workspace.owner.entities.create({
      type: 'doc',
      name: `${prefix} B`,
    })) as { entity: { id: number } };
    const linked = (await workspace.owner.entities.link({
      from_entity_id: a.entity.id,
      to_entity_id: b.entity.id,
      relationship_type_slug: relationshipSlug,
      source: 'api',
    })) as { relationship: { id: number } };

    // Ownership-scoped sources are written by the reconciling subsystem
    // directly, exactly as `channel-about` does — never through the MCP surface.
    if (source) {
      const sql = getTestDb();
      await sql`
        UPDATE entity_relationships SET source = ${source}
        WHERE id = ${linked.relationship.id}
      `;
    }
    return linked.relationship.id;
  }

  async function sourceOf(relationshipId: number): Promise<string | null> {
    const sql = getTestDb();
    const [row] = await sql<{ source: string | null }>`
      SELECT source FROM entity_relationships WHERE id = ${relationshipId}
    `;
    return row.source;
  }

  it('the canonical list covers every value actually stored', () => {
    // The bug in one assertion: these two are written by channel-about and read
    // back by its reconcile, but were absent from the vocabulary entirely.
    expect(RELATIONSHIP_SOURCES).toContain(EDGE_SOURCE_CONFIG);
    expect(RELATIONSHIP_SOURCES).toContain(EDGE_SOURCE_MANUAL);
    expect(RELATIONSHIP_SOURCES).toContain('api');
  });

  it('refuses to move a config-owned edge out of its reconcile scope', async () => {
    const id = await seedEdge('Config', EDGE_SOURCE_CONFIG);

    // THE DEFECT: update_link COALESCEs the new source over the old one. The
    // edge would stop matching `source = 'config'`, so the connection's sweep
    // would never retire it and no other sweep would claim it.
    await expect(
      workspace.owner.entities.manage({
        action: 'update_link',
        relationship_id: id,
        source: 'api',
      })
    ).rejects.toThrow(/cannot change source/i);

    expect(await sourceOf(id)).toBe(EDGE_SOURCE_CONFIG);
  });

  it('refuses to move a manual-owned edge out of its reconcile scope', async () => {
    const id = await seedEdge('Manual', EDGE_SOURCE_MANUAL);
    await expect(
      workspace.owner.entities.manage({
        action: 'update_link',
        relationship_id: id,
        source: 'ui',
      })
    ).rejects.toThrow(/cannot change source/i);
    expect(await sourceOf(id)).toBe(EDGE_SOURCE_MANUAL);
  });

  it('still allows an ordinary source change between authored values', async () => {
    const id = await seedEdge('Plain');
    await workspace.owner.entities.manage({
      action: 'update_link',
      relationship_id: id,
      source: 'llm',
    });
    expect(await sourceOf(id)).toBe('llm');
  });

  it('a no-op write of the same ownership-scoped source is not a reassignment', async () => {
    // The guard must key on the edge MOVING scope, not on the value being
    // present — otherwise an idempotent rewrite by the owning subsystem throws.
    const id = await seedEdge('Idempotent', EDGE_SOURCE_CONFIG);
    const { validateSourceReassignment } = await import(
      '../../../utils/relationship-validation'
    );
    expect(() =>
      validateSourceReassignment(EDGE_SOURCE_CONFIG, EDGE_SOURCE_CONFIG)
    ).not.toThrow();
    expect(await sourceOf(id)).toBe(EDGE_SOURCE_CONFIG);
  });

  it('refuses to let a caller stamp an ownership-scoped source onto any edge', async () => {
    const a = (await workspace.owner.entities.create({
      type: 'doc',
      name: 'Forge A',
    })) as { entity: { id: number } };
    const b = (await workspace.owner.entities.create({
      type: 'doc',
      name: 'Forge B',
    })) as { entity: { id: number } };

    // Enrolling an arbitrary edge in a connection's config sweep would hand it
    // to a reconcile that deletes everything it did not itself put there.
    await expect(
      workspace.owner.entities.link({
        from_entity_id: a.entity.id,
        to_entity_id: b.entity.id,
        relationship_type_slug: relationshipSlug,
        source: EDGE_SOURCE_CONFIG as 'api',
      })
    ).rejects.toThrow(/invalid source/i);
  });
});

